prompt --application/shared_components/automations/avisar_sobre_envio_de_e_mail
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(462712394949764351)
,p_name=>'Avisar sobre envio de E-mail'
,p_static_id=>'avisar-sobre-envio-de-e-mail'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=9;BYMINUTE=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT *',
'FROM ilu_iluminacao',
'WHERE ind_email = ''N'''))
,p_include_rowid_column=>false
,p_commit_each_row=>false
,p_error_handling_type=>'IGNORE'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(462712680963764353)
,p_automation_id=>wwv_flow_imp.id(462712394949764351)
,p_name=>unistr('Enviar email se n\00E3o tiver enviado.')
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    CURSOR c_projecao IS',
'        SELECT i.evento,',
'            MAX(i.tip_iluminacao) as tip_iluminacao,',
'            i.cor,',
'            MAX(i.dat_inicio) as dat_inicio,',
'            MAX(i.dat_termino) as dat_fim,',
'            i.solicitante_contato',
'        FROM ilu_iluminacao i',
unistr('        WHERE i.tip_iluminacao = ''Proje\00E7\00E3o'''),
'            AND i.ind_email = ''S''',
'        GROUP BY',
'            i.evento,',
'            i.cor,',
'            i.solicitante_contato,',
'            i.processo_documento',
'        HAVING TRUNC(MAX(i.dat_inicio)) = TRUNC(SYSDATE) + 5;',
'    ',
'    CURSOR c_iluminacao IS',
'        SELECT i.evento,',
'            MAX(i.tip_iluminacao) as tip_iluminacao,',
'            i.cor,',
'            MAX(i.dat_inicio) as dat_inicio,',
'            MAX(i.dat_termino) as dat_fim,',
'            i.solicitante_contato',
'        FROM ilu_iluminacao i',
unistr('        WHERE i.tip_iluminacao IN (''Iluminaca\00E7\00E3o Completa'', ''Anexo I'', ''C\00FApula'')'),
'            AND i.ind_email = ''S''',
'        GROUP BY',
'            i.evento,',
'            i.cor,',
'            i.solicitante_contato,',
'            i.processo_documento',
'        HAVING TRUNC(MAX(i.dat_inicio)) = TRUNC(SYSDATE) + 5;',
'',
'        v_body_proj CLOB;',
'        v_body_ilu  CLOB;',
'',
'        v_count_proj    NUMBER := 0;',
'        v_count_ilu    NUMBER := 0;',
'BEGIN',
'    v_body_proj := ',
unistr('        ''<b>Proje\00E7\00F5es com in\00EDcio em 5 dias</b><br><br>'' ||'),
'        ''<table border="1" cellpadding="5">'' ||',
'        ''<tr>',
'            <th>Evento</th>',
'            <th>Cor</th>',
unistr('            <th>In\00EDcio</th>'),
'            <th>Fim</th>',
'            <th>Contato</th>',
'        </tr>'';',
'    ',
'    FOR r IN c_projecao LOOP',
'        v_count_proj := v_count_proj + 1;',
'',
'        v_body_proj := v_body_proj ||',
'            ''<tr>'' ||',
'            ''<td>'' || r.evento || ''</td>'' ||',
'            ''<td>'' || r.cor || ''</td>'' ||',
'            ''<td>'' || TO_CHAR(r.dat_inicio,''dd/mm/yyyy hh24:mi'') || ''</td>'' ||',
'            ''<td>'' || TO_CHAR(r.dat_fim,''dd/mm/yyyy hh24:mi'') || ''</td>'' ||',
'            ''<td>'' || r.solicitante_contato || ''</td>'' ||',
'            ''</tr>'';',
'    END LOOP;',
'',
'    v_body_proj := v_body_proj || ''</table><br>'' ||',
'        ''Lembrete: Enviar email para a CEB solicitando o desligamento das luzes.'';',
'',
'    v_body_ilu := ',
unistr('        ''<b>Ilumina\00E7\00F5es com in\00EDcio em 5 dias</b><br><br>'' ||'),
'        ''<table border="1" cellpadding="5">'' ||',
'        ''<tr>',
'            <th>Evento</th>',
'            <th>Tipo</th>',
'            <th>Cor</th>',
unistr('            <th>In\00EDcio</th>'),
'            <th>Fim</th>',
'            <th>Contato</th>',
'        </tr>'';',
'',
'    FOR r IN c_iluminacao LOOP',
'        v_count_ilu := v_count_ilu + 1;',
'',
'        v_body_ilu := v_body_ilu ||',
'            ''<tr>'' ||',
'            ''<td>'' || r.evento || ''</td>'' ||',
'            ''<td>'' || r.tip_iluminacao || ''</td>'' ||',
'            ''<td>'' || r.cor || ''</td>'' ||',
'            ''<td>'' || TO_CHAR(r.dat_inicio,''dd/mm/yyyy hh24:mi'') || ''</td>'' ||',
'            ''<td>'' || TO_CHAR(r.dat_fim,''dd/mm/yyyy hh24:mi'') || ''</td>'' ||',
'            ''<td>'' || r.solicitante_contato || ''</td>'' ||',
'            ''</tr>'';',
'    END LOOP;',
'',
'    v_body_ilu := v_body_ilu || ''</table><br>'' ||',
unistr('        ''Lembrete: Solicitar retirada de pel\00EDculas.'';'),
'',
'    IF v_count_proj > 0 THEN',
'        apex_mail.send(',
'            p_to        => ''marcelo.kobayashi@senado.leg.br'',',
'            p_from      => ''marcelo.kobayashi@senado.leg.br'',',
unistr('            p_subj      => ''Aviso - Proje\00E7\00F5es em 5 dias'','),
'            p_body      => NULL,',
'            p_body_html => v_body_proj',
'        );',
'    END IF;',
'    ',
'    IF v_count_ilu > 0 THEN',
'        apex_mail.send(',
'            p_to        => ''marcelo.kobayashi@senado.leg.br'',',
'            p_from      => ''marcelo.kobayashi@senado.leg.br'',',
unistr('            p_subj      => ''Aviso - Ilumina\00E7\00F5es em 5 dias'','),
'            p_body      => NULL,',
'            p_body_html => v_body_ilu',
'        );',
'    END IF;',
'',
'    COMMIT;',
'    apex_mail.push_queue;',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
end;
/
