,p_plug_display_sequence=>80
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    i.cor AS "Cor",',
unistr('    MIN(i.dat_solicitacao) AS "Data da Solicita\00E7\00E3o",'),
'    i.solicitante_contato AS "Solicitado",',
'    i.processo_documento AS "Processo/Documento",',
'    -- link do processo',
unistr('    LISTAGG(DISTINCT NVL(i.autorizacao, ''N\00E3o informado''), ''<br>'') '),
unistr('        WITHIN GROUP (ORDER BY i.autorizacao) AS "Autoriza\00E7\00E3o",'),
unistr('    -- link da autoriza\00E7\00E3o'),
'    NVL(i.evento, ''Sem evento informado'') AS "Evento",',
'    MIN(i.dat_inicio) || '' a '' || MAX(i.dat_termino) AS "Data do Evento",',
'    LISTAGG(DISTINCT NVL(i.observacao, ''''), ''<br>'') ',
unistr('        WITHIN GROUP (ORDER BY i.observacao) AS "Observa\00E7\00E3o",'),
unistr('    LISTAGG(DISTINCT NVL(i.noticias, ''Sem not\00EDcias''), ''<br>'') '),
unistr('    WITHIN GROUP (ORDER BY i.noticias) AS "Not\00EDcia"'),
'    FROM ilu_iluminacao i',
'    WHERE',
'        (',
'            :P100_COR IS NULL',
'            OR i.cor IN (',
'                SELECT TRIM(COLUMN_VALUE)',
'                FROM TABLE(apex_string.split(:P100_COR, '':''))',
'            )',
'        )',
'        AND (',
'            :P100_ENTREGUE IS NULL',
'            OR i.ind_entregue = :P100_ENTREGUE',
'        )',
'        AND (',
'            :P100_EMAIL IS NULL',
'            OR i.ind_email = :P100_EMAIL',
'        )',
'        AND (',
'            :P100_EMPRESA IS NULL',
'            OR i.empresa = :P100_EMPRESA',
'        )',
'        AND (',
'            :P100_EVENTO IS NULL OR',
'            LOWER(TRANSLATE(i.evento,',
unistr('                ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''))',
'            LIKE ''%'' || LOWER(TRANSLATE(:P100_EVENTO,',
unistr('                ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc'')) || ''%''',
'        )',
'        AND (:P100_TIPO IS NULL OR LOWER(i.tip_iluminacao) = LOWER(:P100_TIPO))',
'        AND (',
'            (:P100_DAT_INICIO IS NULL AND :P100_DAT_FIM IS NULL)',
'            OR (:P100_DAT_INICIO IS NULL AND i.dat_inicio <= :P100_DAT_FIM)',
'            OR (:P100_DAT_FIM IS NULL AND i.dat_inicio >= :P100_DAT_INICIO)',
'            OR (i.dat_inicio BETWEEN :P100_DAT_INICIO AND :P100_DAT_FIM)',
'        )',
'        AND (:P100_PROCESSO IS NULL OR i.processo_documento LIKE :P100_PROCESSO || ''%'')',
'        AND (',
'            :P100_SOLICITANTE IS NULL OR',
'            LOWER(TRANSLATE(i.solicitante_contato,',
