wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1282404283620051155)
,p_plug_name=>'Iluminacoes'
,p_region_name=>'os_todos'
,p_parent_plug_id=>wwv_flow_imp.id(1282404029285051153)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(519416879738522989)
,p_plug_display_sequence=>30
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html CLOB := '''';',
'    v_tem_registro BOOLEAN := FALSE;',
'BEGIN',
'    v_html := v_html || ''',
'        <div class="iluminacao-list" ',
'             style="font-family:Arial, sans-serif;',
'                    max-height:500px;',
'                    overflow-y:auto;',
'                    border:1px solid #ddd;',
'                    border-radius:6px;">'';',
'',
'    FOR r IN (',
'        SELECT ',
'            MIN(i.id_iluminacao) AS id_iluminacao,',
'            i.processo_documento,',
'            TRIM(',
'                REGEXP_REPLACE(',
'                    i.solicitante_contato,',
'                    ''Contato.*$'',',
'                    '''',',
'                    1,',
'                    1,',
'                    ''n''',
'                )',
'            ) AS solicitante_nome,',
'            TRIM(',
'                REGEXP_SUBSTR(',
'                    i.solicitante_contato,',
'                    ''Contato.*$'',',
'                    1,',
'                    1,',
'                    ''n''',
'                )',
'            ) AS solicitante_detalhes,',
'            i.solicitante_contato,',
'            i.cor,',
'            NVL(i.evento, ''Sem evento informado'') AS evento,',
'            LISTAGG(DISTINCT NVL(i.tip_iluminacao, ''Sem tipo informado''), '', '') ',
'                WITHIN GROUP (ORDER BY i.tip_iluminacao) AS tipos,',
'            MIN(i.dat_solicitacao) AS dat_solicitacao,',
'            MIN(i.dat_inicio) AS dat_inicio,',
'            MAX(i.dat_termino) AS dat_termino,',
unistr('            LISTAGG(DISTINCT NVL(i.noticias, ''Sem not\00EDcias''), ''<br>'') '),
'                WITHIN GROUP (ORDER BY i.noticias) AS noticias,',
'            LISTAGG(DISTINCT NVL(i.observacao, ''''), ''<br>'') ',
'                WITHIN GROUP (ORDER BY i.observacao) AS observacoes,',
unistr('            LISTAGG(DISTINCT NVL(i.autorizacao, ''N\00E3o informado''), ''<br>'') '),
'                WITHIN GROUP (ORDER BY i.autorizacao) AS autorizacoes',
'        FROM ilu_iluminacao i',
'        WHERE',
'            (',
'                :P100_COR IS NULL',
'                OR i.cor IN (',
'                    SELECT TRIM(COLUMN_VALUE)',
'                    FROM TABLE(apex_string.split(:P100_COR, '':''))',
'                )',
'            )',
'            AND (',
'                :P100_ENTREGUE IS NULL',
'                OR i.ind_entregue = :P100_ENTREGUE',
'            )',
'            AND (',
'                :P100_EMAIL IS NULL',
'                OR i.ind_email = :P100_EMAIL',
'            )',
'            AND (',
'                :P100_EMPRESA IS NULL',
'                OR i.empresa = :P100_EMPRESA',
'            )',
'            AND (',
'                :P100_EVENTO IS NULL OR',
'                LOWER(TRANSLATE(i.evento,',
unistr('                    ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                    ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''))',
'                LIKE ''%'' || LOWER(TRANSLATE(:P100_EVENTO,',
unistr('                    ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                    ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc'')) || ''%''',
'            )',
'            AND (:P100_TIPO IS NULL OR LOWER(i.tip_iluminacao) = LOWER(:P100_TIPO))',
'            AND (',
'                (:P100_DAT_INICIO IS NULL AND :P100_DAT_FIM IS NULL)',
'                OR (:P100_DAT_INICIO IS NULL AND i.dat_inicio <= :P100_DAT_FIM)',
'                OR (:P100_DAT_FIM IS NULL AND i.dat_inicio >= :P100_DAT_INICIO)',
'                OR (i.dat_inicio BETWEEN :P100_DAT_INICIO AND :P100_DAT_FIM)',
'            )',
'            AND (:P100_PROCESSO IS NULL OR i.processo_documento LIKE :P100_PROCESSO || ''%'')',
'            AND (',
'                :P100_SOLICITANTE IS NULL OR',
'                LOWER(TRANSLATE(i.solicitante_contato,',
unistr('                    ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                    ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''))',
'                LIKE',
'                ''%'' || LOWER(TRANSLATE(:P100_SOLICITANTE,',
unistr('                    ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                    ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc'')) || ''%''',
'            )',
'        GROUP BY ',
'            i.processo_documento,',
'            i.solicitante_contato,',
'            i.cor,',
'            i.evento',
'        ORDER BY MIN(i.dat_inicio) DESC',
'    ) LOOP',
'        BEGIN',
'            v_tem_registro := TRUE;',
'',
'            v_html := v_html || ''',
'                <div class="iluminacao-item"',
'                     id="ilum_'' || TO_CHAR(r.id_iluminacao) || ''"',
'                     data-cor="'' || LOWER(r.cor) || ''" ',
'                     style="display:flex;',
'                            justify-content:space-between;',
'                            align-items:flex-start;',
'                            padding:12px;',
'                            border-bottom:1px solid #eee;',
'                            border-left:8px solid '' || ',
'                                CASE ',
'                                    WHEN r.cor = ''Roxo'' OR r.cor = ''Roxa'' THEN ''#9b59b6'' ',
'                                    WHEN r.cor = ''Preto'' THEN ''#000000'' ',
'                                    WHEN r.cor = ''Azul'' THEN ''#3498db'' ',
'                                    WHEN r.cor = ''Verde'' THEN ''#2ecc71''',
'                                    WHEN r.cor = ''Amarelo'' THEN ''#f1c40f'' ',
'                                    WHEN r.cor = ''Rosa'' THEN ''#e91e63'' ',
'                                    WHEN r.cor = ''Vermelho'' THEN ''#e74c3c'' ',
'                                    WHEN r.cor = ''Cinza'' THEN ''#95a5a6'' ',
'                                    WHEN r.cor = ''Laranja'' THEN ''#e67e22'' ',
'                                    WHEN r.cor = ''Marrom'' THEN ''#8e5c42'' ',
unistr('                                    WHEN r.cor = ''Lil\00E1s'' THEN ''#b57edc'' '),
'                                    WHEN r.cor = ''Roxo Escuro'' THEN ''#4b0082'' ',
'                                    WHEN r.cor = ''Branco'' THEN ''#ffffff'' ',
'                                    ELSE ''#cccccc'' ',
'                                END || '';',
'                            border-radius:4px;">'';',
'',
'            v_html := v_html || ''',
'                <div class="iluminacao-content" style="flex:1;">',
'                    <div style="font-size:16px;',
'                                font-weight:bold;',
'                                color:#2c3e50;',
'                                margin-bottom:4px;',
'                                background-color:#e8f4fd;',
'                                padding:4px 8px;',
'                                border-radius:4px;',
'                                display:inline-block;">'' ',
'                        || NVL(r.evento, ''Sem evento informado'') || ',
'                    ''</div>',
'',
'                    <div style="font-size:13px;color:#555;margin-top:2px;">',
'                        <b>Solicitante:</b> ',
'                        <span style="font-weight:bold;',
'                                     background-color:#f0f8ff;',
'                                     color:#2c3e50;',
'                                     padding:2px 6px;',
'                                     border-radius:4px;',
'                                     display:inline-block;">',
'                            '' || NVL(r.solicitante_nome, ''-'') || ''',
'                        </span><br>',
'',
'                        <b>Contato:</b> ',
'                        <span style="color:#34495e;',
'                                     background-color:#fdfdfd;',
'                                     padding:2px 6px;',
'                                     border-radius:4px;',
'                                     display:inline-block;">',
'                            '' || NVL(r.solicitante_detalhes, ''-'') || ''',
'                        </span><br>',
'                        ',
'                        <b>Processo:</b> '' || r.processo_documento || ''',
'                    </div>',
'',
'                    <div style="font-size:13px;color:#666;margin-top:6px;">',
'                        <b>Cor:</b> '' || r.cor || ''<br>',
'                        <b>Tipo(s):</b> '' || r.tipos || ''',
'                    </div>',
'',
'                    <div style="font-size:12px;color:#777;margin-top:6px;">',
unistr('                        <b>In\00EDcio:</b> '' || TO_CHAR(r.dat_inicio, ''DD/MM/YYYY'') || '),
'                        '' &nbsp;&nbsp; <b>Fim:</b> '' || TO_CHAR(r.dat_termino, ''DD/MM/YYYY'') || ''',
'                    </div>',
'',
'                    <div style="font-size:12px;color:#888;margin-top:6px;">',
unistr('                        <b>Autoriza\00E7\00E3o:</b><br>'' || NVL(r.autorizacoes, ''\2014'') || '''),
'                    </div>',
'                </div>',
'',
'                <div style="font-size:20px;color:#bbb;margin-left:10px;"> ',
'                    <a class="iluminacao-link" ',
'                       href="'' || APEX_PAGE.GET_URL(',
'                            p_page => 100,',
'                            p_items => ''P100_ID_ILU,P100_EXIBIR'',',
'                            p_values => r.id_iluminacao || '','' || r.processo_documento',
'                        ) || ''">&rsaquo;</a>',
'                </div>',
'            </div>'';',
'        END;',
'    END LOOP;',
'',
'    IF NOT v_tem_registro THEN',
'        v_html := v_html || ''',
'            <div style="padding:20px;',
'                        text-align:center;',
'                        color:#888;',
'                        font-style:italic;">',
unistr('                Nenhum registro de Ilumina\00E7\00E3o encontrado.'),
'            </div>'';',
'    END IF;',
'',
'    v_html := v_html || ''</div>'';',
'',
'    RETURN v_html;',
'END;',
''))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P100_COR,P100_EVENTO,P100_TIPO,P100_DAT_INICIO,P100_DAT_FIM,P100_PROCESSO,P100_SOLICITANTE,P100_EMPRESA,P100_ENTREGUE,P100_EMAIL'
);
end;
