wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1296917232635992280)
,p_plug_name=>'Detalhes'
,p_region_name=>'Detalhes'
,p_parent_plug_id=>wwv_flow_imp.id(1296917969537992287)
,p_region_css_classes=>'detalhes-altos'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(519416879738522989)
,p_plug_display_sequence=>70
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_tipo              ilu_iluminacao.tip_iluminacao%TYPE;',
'    v_dat_solicitacao   ilu_iluminacao.dat_solicitacao%TYPE;',
'    v_solicitante       ilu_iluminacao.solicitante_contato%TYPE;',
'    v_processo          ilu_iluminacao.processo_documento%TYPE;',
'    v_link_processo     ilu_iluminacao.link_processo%TYPE;',
'    v_evento            ilu_iluminacao.evento%TYPE;',
'    v_dat_inicio        ilu_iluminacao.dat_inicio%TYPE;',
'    v_dat_fim           ilu_iluminacao.dat_termino%TYPE;',
'    v_noticias          ilu_iluminacao.noticias%TYPE;',
'    v_observacao        ilu_iluminacao.observacao%TYPE;',
'    v_cor               ilu_iluminacao.cor%TYPE;',
'    v_html              CLOB := '''';',
'    v_tem_autorizacao   BOOLEAN := FALSE;',
'BEGIN',
'    -- Buscar os dados principais do registro selecionado',
'    SELECT ',
'        tip_iluminacao,',
'        dat_solicitacao,',
'        solicitante_contato,',
'        processo_documento,',
'        link_processo,',
'        evento,',
'        dat_inicio,',
'        dat_termino,',
'        noticias,',
unistr('        NVL(observacao, ''N\00E3o h\00E1.''),'),
'        cor',
'    INTO ',
'        v_tipo,',
'        v_dat_solicitacao,',
'        v_solicitante,',
'        v_processo,',
'        v_link_processo,',
'        v_evento,',
'        v_dat_inicio,',
'        v_dat_fim,',
'        v_noticias,',
'        v_observacao,',
'        v_cor',
'    FROM ilu_iluminacao',
'    WHERE id_iluminacao = :P100_ID_ILU;',
'',
'    -- Layout em duas colunas',
'    v_html := v_html || ''<div style="display:flex;justify-content:space-between;gap:40px;">'';',
'',
'    -- COLUNA ESQUERDA',
'    v_html := v_html || ''<div style="flex:1;">'' ||',
unistr('                       ''<div><b>Tipo</b><br>''||NVL(v_tipo, ''N\00E3o informado'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Solicitante/Contato</b><br>''||NVL(v_solicitante, ''N\00E3o informado'')||''</div><br>'';'),
'',
unistr('    -- Processo clic\00E1vel'),
'    v_html := v_html || ''<div><b>Processo/Documento</b><br>'';',
'    IF v_link_processo IS NOT NULL THEN',
'        v_html := v_html || ''<a href="''||v_link_processo||''" target="_blank" style="color:#0066cc;text-decoration:none;">''||',
'                            NVL(v_processo, ''Ver processo'')||''</a>'';',
'    ELSE',
unistr('        v_html := v_html || NVL(v_processo, ''N\00E3o informado'');'),
'    END IF;',
'    v_html := v_html || ''</div><br>'';',
'',
unistr('    -- Autoriza\00E7\00F5es m\00FAltiplas'),
unistr('    v_html := v_html || ''<div><b>Autoriza\00E7\00F5es</b><br>'';'),
'',
'    FOR a IN (',
'        SELECT autorizacao, link_autorizacao',
'        FROM ilu_iluminacao',
'        WHERE processo_documento = v_processo',
'          AND evento = v_evento',
'          AND solicitante_contato = v_solicitante',
'          AND cor = v_cor',
'          AND autorizacao IS NOT NULL',
'        ORDER BY autorizacao',
'    )',
'    LOOP',
'        v_tem_autorizacao := TRUE;',
'',
'        IF a.link_autorizacao IS NOT NULL AND REGEXP_LIKE(a.autorizacao, ''\d'') THEN',
'            v_html := v_html || ''<a href="''||a.link_autorizacao||''" target="_blank" style="color:#0066cc;text-decoration:none;">''||',
'                                a.autorizacao||''</a><br>'';',
'        ELSE',
'            v_html := v_html || a.autorizacao||''<br>'';',
'        END IF;',
'    END LOOP;',
'',
'    IF NOT v_tem_autorizacao THEN',
unistr('        v_html := v_html || ''Sem autoriza\00E7\00E3o'';'),
'    END IF;',
'',
'    v_html := v_html || ''</div><br>'';',
'',
'    -- Evento',
unistr('    v_html := v_html || ''<div><b>Evento</b><br>''||NVL(v_evento, ''N\00E3o informado'')||''</div><br>'' ||'),
'                       ''</div>'';',
'',
'    -- COLUNA DIREITA',
'    v_html := v_html || ''<div style="flex:1;">'' ||',
unistr('                       ''<div><b>Data de Solicita\00E7\00E3o</b><br>''||'),
unistr('                       NVL(TO_CHAR(v_dat_solicitacao, ''DD/MM/YYYY HH24:MI''), ''Sem data de solicita\00E7\00E3o'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Data de In\00EDcio</b><br>''||'),
'                       TO_CHAR(v_dat_inicio, ''DD/MM/YYYY'')||''</div><br>'' ||',
'                       ''<div><b>Data de Fim</b><br>''||',
'                       TO_CHAR(v_dat_fim, ''DD/MM/YYYY'')||''</div><br>'' ||',
unistr('                       ''<div><b>Cor</b><br>''||NVL(v_cor, ''N\00E3o especificada'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Not\00EDcias</b><br>''||NVL(v_noticias, ''N\00E3o h\00E1 not\00EDcias'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Observa\00E7\00E3o</b><br>''||v_observacao||''</div><br>'' ||'),
'                       ''</div>''; -- fim coluna direita',
'',
'    v_html := v_html || ''</div>''; -- fim layout geral',
'',
'    RETURN v_html;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN ''',
'            <div style="padding:20px;',
'                        text-align:center;',
'                        color:#888;',
'                        font-style:italic;',
'                        font-family:Arial, sans-serif;',
'                        border:1px solid #ddd;',
'                        border-radius:6px;',
'                        background-color:#fafafa;">',
unistr('                Selecione um registro de Ilumina\00E7\00E3o.'),
'            </div>'';',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P100_ID_ILU'
);
