'        const formatoSelecionado = document.getElementById(''reservas_download_format'')?.value;',
'        if (formatoSelecionado === ''PDF'') {',
unistr('            alert(''O seu relat\00F3rio PDF ser\00E1 preparado. A p\00E1gina ser\00E1 atualizada automaticamente ap\00F3s o download.'');'),
'            pdfDownloadIniciado = true;',
'        } else {',
'            setTimeout(function() {',
'                apex.region("reservas").refresh();',
'            }, 500);',
'        }',
'    }',
'});',
'',
'// Listener para quando a janela volta ao foco (detecta fim do download de PDF)',
'window.addEventListener(''focus'', function() {',
'    if (pdfDownloadIniciado) {',
'        apex.region("reservas").refresh();',
'        pdfDownloadIniciado = false;',
'    }',
'});',
'',
unistr('// ------------------- FIM DO C\00D3DIGO DE ATUALIZA\00C7\00C3O AP\00D3S DOWNLOAD -------------------'),
'',
'',
unistr('// ------------------- IN\00CDCIO DO C\00D3DIGO PARA SIMULAR A ABERTURA DA MODAL de DOWNLOAD -------------------'),
'',
'const actionsButton = $(''#reservas_actions_button'');',
'const menuSelector = ''#'' + actionsButton.attr(''data-menu'');',
'',
'if (actionsButton.length === 0) {',
unistr('    console.error("Bot\00E3o ''A\00E7\00F5es'' n\00E3o encontrado.");'),
'    return;',
'}',
'',
unistr('// Passo 1: Abre o menu de ''A\00E7\00F5es'''),
'if (!actionsButton.hasClass(''is-active'')) {',
'    actionsButton.click();',
'}',
'',
'// Passo 2: Espera o menu renderizar e clica no item ''Fazer Download''',
'setTimeout(function() {',
'    const menuElement = $(menuSelector);',
'    const downloadButtonInMenu = menuElement.find(''button:contains("Fazer Download")'');',
'',
'    if (downloadButtonInMenu.length > 0) {',
