 p_id=>wwv_flow_imp.id(387981201224407528)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Deletar Ilumina\00E7\00E3o')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_processo      ilu_iluminacao.processo_documento%TYPE;',
'    v_evento        ilu_iluminacao.evento%TYPE;',
'    v_solicitante   ilu_iluminacao.solicitante_contato%TYPE;',
'    v_cor           ilu_iluminacao.cor%TYPE;',
'    v_tipo          ilu_iluminacao.tip_iluminacao%TYPE;',
'    v_contrato      ilu_iluminacao.fk_id_contrato%TYPE;',
'    v_dt_ini        ilu_iluminacao.dat_inicio%TYPE;',
'    v_dt_fim        ilu_iluminacao.dat_termino%TYPE;',
'',
'    v_qtd_inteira   NUMBER := 0;',
'    v_qtd_cortada   NUMBER := 0;',
'',
'    v_exists        NUMBER;',
'BEGIN',
'    SELECT processo_documento,',
'           evento,',
'           solicitante_contato,',
'           cor,',
'           tip_iluminacao,',
'           fk_id_contrato,',
'           dat_inicio,',
'           dat_termino',
'    INTO v_processo,',
'         v_evento,',
'         v_solicitante,',
'         v_cor,',
'         v_tipo,',
'         v_contrato,',
'         v_dt_ini,',
'         v_dt_fim',
'    FROM ilu_iluminacao',
'    WHERE id_iluminacao = :P100_ID_ILU;',
'',
'    IF v_tipo = ''Anexo I'' THEN',
'        v_qtd_inteira := 8;',
'        v_qtd_cortada := 0;',
unistr('    ELSIF v_tipo = ''C\00FApula'' THEN'),
'        v_qtd_inteira := 36;',
'        v_qtd_cortada := 1;',
unistr('    ELSIF v_tipo = ''Proje\00E7\00E3o'' THEN'),
'        v_qtd_inteira := 0;',
'        v_qtd_cortada := 0;',
'    ELSE',
'        v_qtd_inteira := 44;',
'        v_qtd_cortada := 1;',
'    END IF;',
'',
'    SELECT COUNT(*)',
'    INTO v_exists',
'    FROM ilu_iluminacao i',
'    WHERE i.tip_iluminacao = v_tipo',
'      AND i.cor = v_cor',
'      AND i.fk_id_contrato = v_contrato',
'      AND i.dat_inicio <= v_dt_fim',
'      AND i.dat_termino >= v_dt_ini',
'      AND NOT (',
'            i.processo_documento   = v_processo',
'        AND i.evento              = v_evento',
'        AND i.solicitante_contato = v_solicitante',
'        AND i.cor                 = v_cor',
'      );',
'',
'    DELETE FROM ilu_arq_projecao',
'    WHERE fk_id_iluminacao IN (',
'        SELECT i.id_iluminacao',
'        FROM ilu_iluminacao i',
'        WHERE i.cor = v_cor',
'            AND i.evento = v_evento',
'            AND i.solicitante_contato = v_solicitante',
'            AND i.processo_documento = v_processo',
'    );',
'',
'    DELETE FROM ilu_hor_projecao',
'    WHERE fk_id_iluminacao = :P100_ID_ILU;',
'',
'    DELETE FROM ilu_entrega',
'    WHERE fk_id_iluminacao = :P100_ID_ILU;',
'',
'    DELETE FROM ilu_iluminacao',
'    WHERE processo_documento = v_processo',
'        AND evento = v_evento',
'        AND cor = v_cor',
'        AND solicitante_contato = v_solicitante;',
'',
'    COMMIT;',
'',
'    IF v_exists = 0 THEN',
'        IF v_qtd_inteira > 0 THEN',
'            UPDATE ilu_cor_contrato',
'               SET qtd = qtd + v_qtd_inteira',
'             WHERE fk_id_contrato = v_contrato',
'               AND nom_cor = v_cor',
'               AND ind_contrato = ''N''',
'               AND tip_estoque = ''Inteira'';',
'        END IF;',
'',
'        IF v_qtd_cortada > 0 THEN',
'            UPDATE ilu_cor_contrato',
'               SET qtd = qtd + v_qtd_cortada',
'             WHERE fk_id_contrato = v_contrato',
'               AND nom_cor = v_cor',
'               AND ind_contrato = ''N''',
'               AND tip_estoque = ''Cortada'';',
'        END IF;',
'    END IF;',
'    COMMIT;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(387979567870407519)
,p_internal_uid=>387981201224407528
);
end;
