,p_plug_display_sequence=>10
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    MIN(i.id_iluminacao) AS id_iluminacao,',
'    i.processo_documento,',
'    TRIM(',
'        REGEXP_REPLACE(',
'            i.solicitante_contato,',
'            ''Contato.*$'',',
'            '''',',
'            1,',
'            1,',
'            ''n''',
'        )',
'    ) AS solicitante_nome,',
'    TRIM(',
'        REGEXP_SUBSTR(',
'            i.solicitante_contato,',
'            ''Contato.*$'',',
'            1,',
'            1,',
'            ''n''',
'        )',
'    ) AS solicitante_detalhes,',
'    i.solicitante_contato,',
'    CASE ',
'        WHEN i.cor = ''Roxo'' THEN ''cor-roxo''',
'        WHEN i.cor = ''Preto'' THEN ''cor-preto''',
'        WHEN i.cor = ''Azul'' THEN ''cor-azul''',
'        WHEN i.cor = ''Verde'' THEN ''cor-verde''',
'        WHEN i.cor = ''Amarelo'' THEN ''cor-amarelo''',
'        WHEN i.cor = ''Rosa'' THEN ''cor-rosa''',
'        WHEN i.cor = ''Vermelho'' THEN ''cor-vermelho''',
'        WHEN i.cor = ''Cinza'' THEN ''cor-cinza''',
'        WHEN i.cor = ''Laranja'' THEN ''cor-laranja''',
'        WHEN i.cor = ''Marrom'' THEN ''cor-marrom''',
unistr('        WHEN i.cor = ''Lil\00E1s'' THEN ''cor-lilas'''),
'        WHEN i.cor = ''Roxo Escuro'' THEN ''cor-roxo-escuro''',
'        WHEN i.cor = ''Branco'' THEN ''cor-branco''',
'        ELSE ''cor-padrao''',
'    END AS cor,',
'    NVL(i.evento, ''Sem evento informado'') AS evento,',
'    LISTAGG(DISTINCT NVL(i.tip_iluminacao, ''Sem tipo informado''), '', '') ',
'        WITHIN GROUP (ORDER BY i.tip_iluminacao) AS tipos,',
'    MIN(i.dat_solicitacao) AS dat_solicitacao,',
'    MIN(i.dat_inicio) AS dat_inicio,',
'    MAX(i.dat_termino) AS dat_termino,',
unistr('    LISTAGG(DISTINCT NVL(i.noticias, ''Sem not\00EDcias''), ''<br>'') '),
'        WITHIN GROUP (ORDER BY i.noticias) AS noticias,',
'    LISTAGG(DISTINCT NVL(i.observacao, ''''), ''<br>'') ',
'        WITHIN GROUP (ORDER BY i.observacao) AS observacoes,',
unistr('    LISTAGG(DISTINCT NVL(i.autorizacao, ''N\00E3o informado''), ''<br>'') '),
'        WITHIN GROUP (ORDER BY i.autorizacao) AS autorizacoes',
'FROM ilu_iluminacao i',
'GROUP BY ',
'    i.processo_documento,',
'    i.solicitante_contato,',
'    i.cor,',
'    i.evento;',
''))
