,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    nom_cor,',
'    marca,',
'    SUM(',
'        CASE ',
'            WHEN tip_estoque = ''Inteira''',
'                AND ind_contrato = ''N''',
'                AND fk_id_contrato = 1',
'            THEN qtd',
'',
'            WHEN ind_contrato = ''S''',
'                AND fk_id_contrato = 61',
'            THEN qtd',
'        ',
'            ELSE 0 ',
'        ',
