wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1045166647692653612)
,p_name=>'P101_TIPO'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(1282437342438055582)
,p_prompt=>'Tipo'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH periodo AS (',
'    SELECT DISTINCT tip_iluminacao',
'    FROM ilu_iluminacao',
'    WHERE dat_inicio  <= :P101_DATA_FIM',
'      AND dat_termino >= :P101_DATA_INICIO',
')',
'SELECT DISTINCT',
'       INITCAP(t.tip_iluminacao) AS d,',
'       t.tip_iluminacao          AS r',
'FROM ilu_iluminacao t',
'WHERE',
'(',
unistr('    -- CONTRATO 61: s\00F3 proje\00E7\00E3o'),
'    :P101_CONTRATO = 61',
unistr('    AND t.tip_iluminacao = ''Proje\00E7\00E3o'''),
')',
'OR',
'(',
unistr('    -- DEMAIS CONTRATOS: NUNCA mostrar proje\00E7\00E3o'),
'    :P101_CONTRATO <> 61',
unistr('    AND t.tip_iluminacao <> ''Proje\00E7\00E3o'''),
'    AND',
'    (',
'        (',
'            EXISTS (',
'                SELECT 1',
'                FROM periodo',
unistr('                WHERE tip_iluminacao = ''Ilumina\00E7\00E3o Completa'''),
'            )',
unistr('            AND t.tip_iluminacao = ''Ilumina\00E7\00E3o Completa'''),
'        )',
'        OR',
'        (',
'            NOT EXISTS (',
'                SELECT 1',
'                FROM periodo',
unistr('                WHERE tip_iluminacao = ''Ilumina\00E7\00E3o Completa'''),
'            )',
'            AND EXISTS (',
'                SELECT 1',
'                FROM periodo',
unistr('                WHERE tip_iluminacao IN (''C\00FApula'', ''Anexo I'')'),
'            )',
unistr('            AND t.tip_iluminacao IN (''C\00FApula'', ''Anexo I'')'),
'        )',
'        OR',
'        (',
'            (SELECT COUNT(*) FROM periodo) = 0',
'        )',
'    )',
');',
''))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('Sem tipo espec\00EDfico')
,p_lov_cascade_parent_items=>'P101_DATA_INICIO,P101_DATA_FIM,P101_CONTRATO'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(519492983389523071)
,p_item_template_options=>'#DEFAULT#'
,p_warn_on_unsaved_changes=>'I'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'NONE'
,p_attribute_02=>'N'
);
