wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1045167759225653623)
,p_name=>'P101_COR'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(1282437342438055582)
,p_prompt=>'Cor'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH ilu_completa AS (',
'    SELECT DISTINCT ilu.cor',
'    FROM ilu_iluminacao ilu',
'    WHERE ilu.fk_id_contrato = :P101_CONTRATO',
unistr('      AND ilu.tip_iluminacao = ''Ilumina\00E7\00E3o Completa'''),
'      AND ilu.dat_inicio <= :P101_DATA_FIM',
'      AND ilu.dat_termino >= :P101_DATA_INICIO',
'),',
'',
unistr('-- C\00FApula no per\00EDodo'),
'ilu_cupula AS (',
'    SELECT DISTINCT ilu.cor',
'    FROM ilu_iluminacao ilu',
'    WHERE ilu.fk_id_contrato = :P101_CONTRATO',
unistr('      AND ilu.tip_iluminacao = ''C\00FApula'''),
'      AND ilu.dat_inicio <= :P101_DATA_FIM',
'      AND ilu.dat_termino >= :P101_DATA_INICIO',
'),',
'',
unistr('-- Anexo I no per\00EDodo'),
'ilu_anexo AS (',
'    SELECT DISTINCT ilu.cor',
'    FROM ilu_iluminacao ilu',
'    WHERE ilu.fk_id_contrato = :P101_CONTRATO',
'      AND ilu.tip_iluminacao = ''Anexo I''',
'      AND ilu.dat_inicio <= :P101_DATA_FIM',
'      AND ilu.dat_termino >= :P101_DATA_INICIO',
')',
'',
unistr('-- PROJE\00C7\00C3O \00BF s\00F3 Preto'),
'SELECT ''Preto'' AS d,',
'       ''Preto'' AS r',
'FROM dual',
unistr('WHERE :P101_TIPO = ''PROJE\00C7\00C3O'''),
'',
'UNION ALL',
'',
unistr('-- ILUMINA\00C7\00C3O COMPLETA + j\00E1 existe no per\00EDodo \00BF s\00F3 a cor j\00E1 usada'),
'SELECT INITCAP(cor) AS d,',
'       cor AS r',
'FROM ilu_completa',
unistr('WHERE :P101_TIPO = ''Ilumina\00E7\00E3o Completa'''),
'',
'UNION ALL',
'',
'SELECT INITCAP(cor) AS d,',
'       cor AS r',
'FROM ilu_cupula',
unistr('WHERE :P101_TIPO = ''C\00FApula'''),
'',
'UNION ALL',
'',
unistr('-- ANEXO I \00BF se j\00E1 existe no per\00EDodo, s\00F3 a cor usada'),
'SELECT INITCAP(cor) AS d,',
'       cor AS r',
'FROM ilu_anexo',
'WHERE :P101_TIPO = ''Anexo I''',
'',
'UNION ALL',
'',
unistr('-- Demais casos \00BF todas as cores do contrato'),
'SELECT DISTINCT INITCAP(nom_cor) AS d,',
'       nom_cor AS r',
'FROM ilu_cor_contrato',
'WHERE fk_id_contrato = :P101_CONTRATO',
'  AND (',
unistr('        (:P101_TIPO = ''Ilumina\00E7\00E3o Completa'' AND NOT EXISTS (SELECT 1 FROM ilu_completa))'),
unistr('     OR (:P101_TIPO = ''C\00FApula''               AND NOT EXISTS (SELECT 1 FROM ilu_cupula))'),
'     OR (:P101_TIPO = ''Anexo I''              AND NOT EXISTS (SELECT 1 FROM ilu_anexo))',
unistr('     OR (:P101_TIPO NOT IN (''PROJE\00C7\00C3O'',''Ilumina\00E7\00E3o Completa'',''C\00FApula'',''Anexo I''))'),
'      );',
''))
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P101_CONTRATO,P101_DATA_INICIO,P101_DATA_FIM,P101_TIPO'
,p_ajax_optimize_refresh=>'Y'
