wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(458492542541070303)
,p_event_id=>wwv_flow_imp.id(458492477336070302)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_solicitante_contato  ilu_iluminacao.solicitante_contato%TYPE;',
'BEGIN',
'    SELECT',
'        solicitante_contato,',
'        processo_documento,',
'        link_processo',
'    INTO',
'        v_solicitante_contato,',
'        :P101_PROCESSO,',
'        :P101_LINK_PROCESSO',
'    FROM ilu_iluminacao',
'    WHERE dat_solicitacao = :P101_DAT_SOLICITACAO',
'    FETCH FIRST 1 ROWS ONLY;',
'',
'    -- Parte antes de "Contato"',
'    :P101_SOLICITANTE :=',
'        TRIM(',
'            SUBSTR(',
'                v_solicitante_contato,',
'                1,',
'                INSTR(v_solicitante_contato, ''Contato'') - 1',
'            )',
'        );',
'',
'    -- Parte a partir de "Contato"',
'    :P101_CONTATO :=',
'        TRIM(',
'            SUBSTR(',
'                v_solicitante_contato,',
'                INSTR(v_solicitante_contato, ''Contato'')',
'            )',
'        );',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P101_SOLICITANTE  := NULL;',
'        :P101_CONTATO     := ''Contato: '';',
'        :P101_PROCESSO    := NULL;',
'        :P101_LINK_PROCESSO := NULL;',
'END;',
''))
,p_attribute_02=>'P101_DAT_SOLICITACAO'
,p_attribute_03=>'P101_SOLICITANTE,P101_CONTATO,P101_PROCESSO,P101_LINK_PROCESSO'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
