'    v_id_iluminacao     ilu_iluminacao.id_iluminacao%TYPE;',
'',
'    v_qtd_peliculas_inteira   NUMBER;',
'    v_qtd_peliculas_cortada   NUMBER;',
'',
'    v_qtd_estoque_inteira     NUMBER;',
'    v_qtd_estoque_cortada     NUMBER;',
'',
'    v_exists NUMBER;',
'',
'    v_cor           VARCHAR2(100);',
'    v_ind_entregue  VARCHAR2(1);',
'',
'    v_data  DATE;',
'BEGIN',
unistr('    IF :P101_TIPO = ''Proje\00E7\00E3o'' THEN'),
'        v_cor := ''Preto'';',
'        v_ind_entregue := '''';',
'    ELSE',
'        v_cor := :P101_COR;',
'        v_ind_entregue := ''N'';',
'    END IF;',
'',
unistr('    v_observacao := NVL(:P101_OBSERVACAO, ''N\00E3o h\00E1.'');'),
'',
'    IF :P101_TIPO = ''Anexo I'' THEN',
'        v_qtd_peliculas_inteira := 8;',
'        v_qtd_peliculas_cortada := 0;',
'',
unistr('    ELSIF :P101_TIPO = ''C\00FApula'' THEN'),
'        v_qtd_peliculas_inteira := 36;',
'        v_qtd_peliculas_cortada := 1;',
'',
unistr('    ELSIF :P101_TIPO = ''Proje\00E7\00E3o'' THEN'),
'        v_qtd_peliculas_inteira := 0;',
'        v_qtd_peliculas_cortada := 0;',
'',
'    ELSE',
'        v_qtd_peliculas_inteira := 44;',
'        v_qtd_peliculas_cortada := 1;',
'    END IF;',
'',
'    SELECT COUNT(*)',
'    INTO v_exists',
'    FROM ilu_iluminacao i',
'    WHERE i.tip_iluminacao = :P101_TIPO',
'      AND i.cor = v_cor',
'      AND i.fk_id_contrato = :P101_CONTRATO',
'      AND (',
'        (i.dat_inicio <= :P101_DATA_FIM',
'        AND i.dat_termino >= :P101_DATA_INICIO)',
'',
'        OR TRUNC(i.dat_termino) = TRUNC(TO_DATE(:P101_DATA_INICIO, ''DD/MM/YYYY'')) - 1',
'        OR TRUNC(i.dat_inicio) = TRUNC(TO_DATE(:P101_DATA_FIM, ''DD/MM/YYYY'')) + 1',
'      );',
'',
'    IF v_exists = 0 THEN',
'        BEGIN',
'            SELECT qtd',
'            INTO v_qtd_estoque_inteira',
'            FROM ilu_cor_contrato',
'            WHERE fk_id_contrato = :P101_CONTRATO',
'              AND nom_cor = v_cor',
'              AND ind_contrato = ''N''',
'              AND tip_estoque = ''Inteira'';',
'        EXCEPTION WHEN NO_DATA_FOUND THEN',
'            v_qtd_estoque_inteira := 0;',
'        END;',
'',
'        BEGIN',
'            SELECT qtd',
'            INTO v_qtd_estoque_cortada',
'            FROM ilu_cor_contrato',
'            WHERE fk_id_contrato = :P101_CONTRATO',
'              AND nom_cor = v_cor',
'              AND ind_contrato = ''N''',
'              AND tip_estoque = ''Cortada'';',
'        EXCEPTION WHEN NO_DATA_FOUND THEN',
'            v_qtd_estoque_cortada := 0;',
'        END;',
'',
'        IF v_qtd_estoque_inteira < v_qtd_peliculas_inteira THEN',
'            RAISE_APPLICATION_ERROR(-20006,',
unistr('            ''Estoque insuficiente de pel\00EDculas inteiras dessa cor.'');'),
'        END IF;',
'',
'        IF v_qtd_peliculas_cortada > 0 THEN',
'',
'            IF v_qtd_estoque_cortada >= v_qtd_peliculas_cortada THEN',
'                NULL;',
'',
'            ELSIF v_qtd_estoque_cortada = 0',
'             AND v_qtd_estoque_inteira >= v_qtd_peliculas_inteira + 0.5 THEN',
'                NULL;',
'',
'            ELSE',
'                RAISE_APPLICATION_ERROR(-20007,',
unistr('                ''Estoque insuficiente de pel\00EDculas cortadas.'');'),
'            END IF;',
'        END IF;',
'',
'        IF v_qtd_peliculas_inteira > 0 THEN',
'            UPDATE ilu_cor_contrato',
'            SET qtd = qtd - v_qtd_peliculas_inteira',
'            WHERE fk_id_contrato = :P101_CONTRATO',
'                AND nom_cor = v_cor',
'                AND ind_contrato = ''N''',
'                AND tip_estoque = ''Inteira'';',
'        END IF;',
'',
'        IF v_qtd_peliculas_cortada > 0 THEN',
'            IF v_qtd_estoque_cortada >= v_qtd_peliculas_cortada THEN',
'                UPDATE ilu_cor_contrato',
'                SET qtd = qtd - v_qtd_peliculas_cortada',
'                WHERE fk_id_contrato = :P101_CONTRATO',
'                    AND nom_cor = v_cor',
'                    AND ind_contrato = ''N''',
'                    AND tip_estoque = ''Cortada'';',
'            ELSE ',
'                UPDATE ilu_cor_contrato',
'                SET qtd = qtd - 1',
'                WHERE fk_id_contrato = :P101_CONTRATO',
'                    AND nom_cor = v_cor',
'                    AND ind_contrato = ''N''',
'                    AND tip_estoque = ''Inteira'';',
'',
'                UPDATE ilu_cor_contrato',
'                SET qtd = qtd + 1',
'                WHERE fk_id_contrato = :P101_CONTRATO',
'                    AND nom_cor = v_cor',
'                    AND ind_contrato = ''N''',
'                    AND tip_estoque = ''Cortada'';',
'            END IF;',
'        END IF;',
'    END IF;',
'',
'    INSERT INTO ilu_iluminacao (',
'        tip_iluminacao,',
'        noticias,',
'        cor,',
'        dat_solicitacao,',
'        dat_inicio,',
'        dat_termino,',
'        solicitante_contato,',
'        processo_documento,',
'        autorizacao,',
'        link_processo,',
'        link_autorizacao,',
'        evento,',
'        observacao,',
'        ind_entregue,',
'        fk_id_contrato,',
'        ind_email,',
'        ind_email_atual',
'    ) VALUES (',
'        :P101_TIPO,',
'        :P101_NOTICIAS,',
'        v_cor,',
'        :P101_DAT_SOLICITACAO,',
'        :P101_DATA_INICIO,',
'        :P101_DATA_FIM,',
'        :P101_SOLICITANTE || '' '' || :P101_CONTATO,',
'        :P101_PROCESSO,',
'        :P101_AUTORIZACAO,',
'        :P101_LINK_PROCESSO,',
'        :P101_LINK_AUTORIZACAO,',
'        :P101_EVENTO,',
'        v_observacao,',
'        v_ind_entregue,',
'        :P101_CONTRATO,',
'        ''N'',',
'        ''N''',
'    )',
'    RETURNING id_iluminacao INTO v_id_iluminacao;',
'',
'    :P101_ID_IL := v_id_iluminacao;',
'',
'    INSERT INTO ilu_iluminacao (',
'        tip_iluminacao,',
'        noticias,',
'        cor,',
'        dat_solicitacao,',
'        dat_inicio,',
'        dat_termino,',
'        solicitante_contato,',
'        processo_documento,',
'        autorizacao,',
'        link_processo,',
'        link_autorizacao,',
'        evento,',
'        observacao,',
'        ind_entregue,',
'        fk_id_contrato,',
'        ind_email,',
'        ind_email_atual',
'    ) VALUES (',
'        :P101_TIPO,',
'        :P101_NOTICIAS,',
'        v_cor,',
'        :P101_DAT_SOLICITACAO,',
'        :P101_DATA_INICIO,',
'        :P101_DATA_FIM,',
'        :P101_SOLICITANTE || '' '' || :P101_CONTATO,',
'        :P101_PROCESSO,',
unistr('        :P101_AUTORIZACAO_2, -- \00BF aqui muda'),
'        :P101_LINK_PROCESSO,',
'        :P101_LINK_AUTORIZACAO,',
'        :P101_EVENTO,',
'        v_observacao,',
'        v_ind_entregue,',
'        :P101_CONTRATO,',
'        ''N'',',
'        ''N''',
'    );',
'',
unistr('    IF :P101_TIPO = ''Proje\00E7\00E3o'' THEN'),
'        v_data := :P101_DATA_INICIO;',
'        WHILE v_data <= :P101_DATA_FIM LOOP',
'            INSERT INTO ilu_hor_projecao (',
'                fk_id_iluminacao,',
'                dat,',
'                hor_inicio,',
'                hor_fim,',
'                ind_teste',
'            ) VALUES (',
'                v_id_iluminacao,',
'                v_data,',
'                :P101_HOR_INICIO,',
'                :P101_HOR_FIM,',
'                CASE',
'                    WHEN :P101_TESTE = ''S''',
'                        AND v_data = :P101_DATA_INICIO',
'                    THEN ''S''',
'                    ELSE ''N''',
'                END',
'            );',
'',
'            v_data := v_data + 1;',
'        END LOOP;',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>388111217283186577
);
end;
