,p_attribute_07=>'Retirada_template.docx'
,p_attribute_11=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'  ''retirada_iluminacao'' AS "filename",',
'  CURSOR(',
'    SELECT',
'      e.id_entrega                    AS "id_entrega",',
'      e.num_recibo                    AS "num_recibo",',
'      e.retirado_por                  AS "retirado_por",',
'',
'      i.id_iluminacao                 AS "id_iluminacao",',
'      i.tip_iluminacao                AS "tipo_iluminacao",',
'      i.evento                        AS "evento",',
'      i.cor                           AS "cor",',
'',
'      TO_CHAR(i.dat_inicio,  ''DD/MM/YYYY'') AS "data_inicio",',
'      TO_CHAR(i.dat_termino, ''DD/MM/YYYY'') AS "data_termino",',
'      TO_CHAR(e.dat_entrega, ''month "de" YYYY'', ''NLS_DATE_LANGUAGE=PORTUGUESE'') AS "data_entrega",',
'',
'      e.qtd_inteiras                  AS "qtd_peliculas_inteiras",',
'      e.qtd_cortadas                  AS "qtd_peliculas_cortadas",',
'      e.fitas                         AS "qtd_fitas_adesivas"',
'',
'    FROM ilu_entrega e',
'         JOIN ilu_iluminacao i',
'           ON i.id_iluminacao = e.fk_id_iluminacao',
'    WHERE e.id_entrega = :P102_ID_ENTREGA',
'  ) AS "data"',
'FROM dual;',
''))
,p_wait_for_result=>'Y'
);
