wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(388123638284212589)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update iluminacoes'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    v_processo_documento   VARCHAR2(4000); ',
'    v_solicitante_contato  VARCHAR2(4000); ',
'    v_evento               VARCHAR2(4000); ',
'    v_cor                  VARCHAR2(100); ',
'BEGIN ',
'    -- Busca dados atuais',
'    SELECT',
'        processo_documento,',
'        solicitante_contato,',
'        evento,',
'        cor',
'    INTO',
'        v_processo_documento,',
'        v_solicitante_contato,',
'        v_evento,',
'        v_cor',
'    FROM ilu_iluminacao',
'    WHERE id_iluminacao = :P102_ID_ILU;',
'',
'    -- Atualiza o registro atual',
'    UPDATE ilu_iluminacao',
'       SET tip_iluminacao       = :P102_TIPO,',
'           noticias             = :P102_NOTICIAS,',
'           cor                  = :P102_COR,',
'           dat_solicitacao      = :P102_DAT_SOLICITACAO,',
'           dat_inicio           = :P102_DATA_INICIO,',
'           dat_termino          = :P102_DATA_FIM,',
'           solicitante_contato  = :P102_SOLICITANTE || '' '' || :P102_CONTATO,',
'           processo_documento   = :P102_PROCESSO,',
'           autorizacao          = :P102_AUTORIZACAO,',
'           link_processo        = :P102_LINK_PROCESSO,',
'           link_autorizacao     = :P102_LINK_AUTORIZACAO,',
'           evento               = :P102_EVENTO,',
'           observacao           = :P102_OBSERVACAO',
'     WHERE id_iluminacao = :P102_ID_ILU;',
'',
'    -- Atualiza registros relacionados',
'    UPDATE ilu_iluminacao',
'       SET tip_iluminacao       = :P102_TIPO,',
'           noticias             = :P102_NOTICIAS,',
'           cor                  = :P102_COR,',
'           dat_solicitacao      = :P102_DAT_SOLICITACAO,',
'           dat_inicio           = :P102_DATA_INICIO,',
'           dat_termino          = :P102_DATA_FIM,',
'           solicitante_contato  = :P102_SOLICITANTE || '' '' || :P102_CONTATO,',
'           processo_documento   = :P102_PROCESSO,',
'           autorizacao          = :P102_AUTORIZACAO_2,',
'           link_processo        = :P102_LINK_PROCESSO,',
'           link_autorizacao     = :P102_LINK_AUTORIZACAO,',
'           evento               = :P102_EVENTO,',
'           observacao           = :P102_OBSERVACAO',
'     WHERE processo_documento   = v_processo_documento',
'       AND solicitante_contato  = v_solicitante_contato',
'       AND evento               = v_evento',
'       AND cor                  = v_cor',
'       AND id_iluminacao       != :P102_ID_ILU;',
'',
'    COMMIT;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        RAISE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(388122355396212588)
,p_internal_uid=>388123638284212589
);
