,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_mime      VARCHAR2(200);',
'    l_filename  VARCHAR2(200);',
'BEGIN',
'    SELECT blob_content, mime_type, filename',
'    INTO l_blob, l_mime, l_filename',
'    FROM apex_application_temp_files',
'    WHERE name = :P102_ARQ_ENTREGA;',
'',
'    UPDATE ilu_entrega',
'    SET arq_entrega = l_blob,',
'        mimetype = l_mime,',
'        filename = l_filename',
'    WHERE id_entrega = :P102_ID_ENTREGA;',
'    ',
'    UPDATE ilu_iluminacao',
'    SET ind_entregue = ''S''',
'    WHERE id_iluminacao = :P102_ID_ILU;',
'END;'))
