,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    MIN(i.id_iluminacao) AS id,',
'    MIN(i.cor) AS "Cor",',
'    MIN(i.solicitante_contato) AS "Solicitado",',
'    MIN(i.processo_documento) AS "Processo",',
'    REPLACE(MIN(i.evento), '' '', ''_'') AS "Evento",',
'    MAX(ind_email_atual) AS email,',
unistr('    MIN(i.dat_solicitacao) AS "Data da Solicita\00E7\00E3o",'),
'    -- link do processo',
unistr('    LISTAGG(DISTINCT NVL(i.autorizacao, ''N\00E3o informado''), ''<br>'') '),
unistr('        WITHIN GROUP (ORDER BY i.autorizacao) AS "Autoriza\00E7\00E3o",'),
unistr('    -- link da autoriza\00E7\00E3o'),
'    MIN(i.dat_inicio) || '' a '' || MAX(i.dat_termino) AS "Data do Evento",',
'    LISTAGG(DISTINCT NVL(i.observacao, ''''), ''<br>'') ',
unistr('        WITHIN GROUP (ORDER BY i.observacao) AS "Observa\00E7\00E3o",'),
unistr('    LISTAGG(DISTINCT NVL(i.noticias, ''Sem not\00EDcias''), ''<br>'') '),
unistr('        WITHIN GROUP (ORDER BY i.noticias) AS "Not\00EDcia"'),
'    FROM ilu_iluminacao i',
'    WHERE',
'        (',
'            :P103_COR IS NULL',
'            OR i.cor IN (',
'                SELECT TRIM(COLUMN_VALUE)',
'                FROM TABLE(apex_string.split(:P103_COR, '':''))',
'            )',
'        )',
'        AND (',
'            :P103_ENTREGUE IS NULL',
'            OR i.ind_entregue = :P103_ENTREGUE',
'        )',
'        AND (',
'            :P103_EMAIL IS NULL',
'            OR i.ind_email = :P103_EMAIL',
'        )',
'        AND (',
'            :P103_EMPRESA IS NULL',
'            OR i.empresa = :P103_EMPRESA',
'        )',
'        AND (',
'            :P103_EVENTO IS NULL OR',
'            LOWER(TRANSLATE(i.evento,',
unistr('                ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''))',
'            LIKE ''%'' || LOWER(TRANSLATE(:P103_EVENTO,',
unistr('                ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc'')) || ''%''',
'        )',
'        AND (:P103_TIPO IS NULL OR LOWER(i.tip_iluminacao) = LOWER(:P103_TIPO))',
'        AND (',
'            (:P103_DAT_INICIO IS NULL AND :P103_DAT_FIM IS NULL)',
'            OR (:P103_DAT_INICIO IS NULL AND i.dat_inicio <= :P103_DAT_FIM)',
'            OR (:P103_DAT_FIM IS NULL AND i.dat_inicio >= :P103_DAT_INICIO)',
'            OR (i.dat_inicio BETWEEN :P103_DAT_INICIO AND :P103_DAT_FIM)',
'        )',
'        AND (:P103_PROCESSO IS NULL OR i.processo_documento LIKE :P103_PROCESSO || ''%'')',
'        AND (',
'            :P103_SOLICITANTE IS NULL OR',
'            LOWER(TRANSLATE(i.solicitante_contato,',
unistr('                ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''))',
'            LIKE',
'            ''%'' || LOWER(TRANSLATE(:P103_SOLICITANTE,',
unistr('                ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc'')) || ''%''',
'        )',
'    GROUP BY ',
'        i.processo_documento,',
'        i.solicitante_contato,',
'        i.cor,',
'        i.evento',
'    ORDER BY MIN(i.dat_inicio) DESC '))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P103_COR,P103_EVENTO,P103_TIPO,P103_DAT_INICIO,P103_DAT_FIM,P103_PROCESSO,P103_SOLICITANTE,P103_EMPRESA,P103_EMAIL,P103_ENTREGUE'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
