wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(388101372651180235)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update iluminacoes'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_processo_documento    VARCHAR2(4000);',
'    v_solicitante_contato   VARCHAR2(4000);',
'    v_evento                VARCHAR2(4000);',
'    v_cor                   VARCHAR2(100);',
'BEGIN',
'    SELECT processo_documento, solicitante_contato, evento, cor',
'    INTO v_processo_documento, v_solicitante_contato, v_evento, v_cor',
'    FROM ilu_iluminacao',
'    WHERE id_iluminacao = :P170_ID_ILU;',
'',
'    UPDATE ilu_iluminacao',
'    SET tip_iluminacao = :P170_TIPO,',
'        noticias = :P170_NOTICIAS,',
'        cor = :P170_COR,',
'        dat_solicitacao = :P170_DAT_SOLICITACAO,',
'        dat_inicio = :P170_DATA_INICIO,',
'        dat_termino = :P170_DATA_FIM,',
'        solicitante_contato = :P170_SOLICITANTE || '' '' || :P170_CONTATO,',
'        processo_documento = :P170_PROCESSO,',
'        autorizacao = :P170_AUTORIZACAO,',
'        link_processo = :P170_LINK_PROCESSO,',
'        link_autorizacao = :P170_LINK_AUTORIZACAO,',
'        evento = :P170_EVENTO,',
'        observacao = :P170_OBSERVACAO',
'    WHERE id_iluminacao = :P170_ID_ILU;',
'',
'    UPDATE ilu_iluminacao',
'    SET tip_iluminacao = :P170_TIPO,',
'        noticias = :P170_NOTICIAS,',
'        cor = :P170_COR,',
'        dat_solicitacao = :P170_DAT_SOLICITACAO,',
'        dat_inicio = :P170_DATA_INICIO,',
'        dat_termino = :P170_DATA_FIM,',
'        solicitante_contato = :P170_SOLICITANTE || '' '' || :P170_CONTATO,',
'        processo_documento = :P170_PROCESSO,',
'        autorizacao = :P170_AUTORIZACAO_2,',
'        link_processo = :P170_LINK_PROCESSO,',
'        link_autorizacao = :P170_LINK_AUTORIZACAO,',
'        evento = :P170_EVENTO,',
'        observacao = :P170_OBSERVACAO',
'    WHERE processo_documento = v_processo_documento',
'      AND solicitante_contato = v_solicitante_contato',
'      AND evento = v_evento',
'      AND cor = v_cor',
'      AND id_iluminacao != :P170_ID_ILU;',
'',
'    COMMIT;',
'    ',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        RAISE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>388101372651180235
);
end;
