wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(458007760220518521)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Enviar Email'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_body   CLOB := '''';',
'    l_lista  CLOB := '''';',
'    l_tabela CLOB := '''';',
'    l_idx    PLS_INTEGER := 0;',
'',
'    FUNCTION cor_css (p_cor VARCHAR2) RETURN VARCHAR2 IS',
'    BEGIN',
'        RETURN CASE UPPER(TRIM(p_cor))',
'            WHEN ''VERMELHO'' THEN ''#C00000''',
'            WHEN ''AZUL''     THEN ''#0070C0''',
'            WHEN ''VERDE''    THEN ''#00B050''',
'            WHEN ''AMARELO''  THEN ''#FFFF00''',
'            WHEN ''LARANJA''  THEN ''#ED7D31''',
'            WHEN ''ROXO''     THEN ''#7030A0''',
'            WHEN ''BRANCO''   THEN ''#FFFFFF''',
'            WHEN ''PRETO''    THEN ''#000000''',
unistr('            ELSE ''#CCCCCC'' -- padr\00E3o'),
'        END;',
'    END;',
'BEGIN',
'    l_body :=',
'        ''Prezados, bom dia!<br><br>'' ||',
unistr('        ''Conforme Ordem de Servi\00E7o n\00BA <b>'' || :P171_NUM_OS ||''</b>, solicito que providenciem a retirada nesta '' ||'),
unistr('        ''<b>ASQUALOG</b> das seguintes pel\00EDculas para serem instaladas em:<br><br>'';'),
'',
'    FOR r IN (',
'        SELECT',
'            i.cor,',
'            MAX(i.dat_inicio) dat_inicio,',
'            MIN(i.dat_solicitacao) dat_solicitacao,',
'            i.solicitante_contato,',
'            i.processo_documento,',
'            LISTAGG(DISTINCT NVL(i.autorizacao,''-''), ''<br>'')',
'                WITHIN GROUP (ORDER BY i.autorizacao) autorizacao,',
'            i.evento,',
'            MIN(i.dat_inicio) || '' a '' || MAX(i.dat_termino) data_evento',
'        FROM ilu_iluminacao i',
'        WHERE ind_email_atual = ''S''',
unistr('            AND tip_iluminacao <> ''Proje\00E7\00E3o'''),
'        GROUP BY',
'            i.cor,',
'            i.solicitante_contato,',
'            i.processo_documento,',
'            i.evento',
'        ORDER BY MIN(i.dat_inicio)',
'    ) LOOP',
'        l_idx := l_idx + 1;',
'',
'        l_lista := l_lista ||',
'            ''<li>'' ||',
'            TO_CHAR(r.dat_inicio, ''DD/MM/YYYY'') || '': '' ||',
unistr('            APEX_APPLICATION.g_f01(l_idx) || '' pel\00EDculas cortadas e '' ||'),
unistr('            APEX_APPLICATION.g_f02(l_idx) || '' pel\00EDculas inteiras na '' ||'),
'            ''<b>COR '' || r.cor || ''</b>, juntamente com '' ||',
unistr('            APEX_APPLICATION.g_f03(l_idx) || '' rolos de fita adesiva, para instala\00E7\00E3o no per\00EDodo de '' ||'),
unistr('            r.data_evento || '', em alus\00E3o ao evento '' || r.evento || ''.'' ||'),
'            ''</li>'';',
'',
'        l_tabela := l_tabela ||',
'            ''<tr>'' ||',
'            ''<td style="background-color:'' || cor_css(r.cor) || ''; width:30px;"></td>'' ||',
'            ''<td align="center">'' || TO_CHAR(r.dat_solicitacao, ''DD/MM/YYYY'') || ''</td>'' ||',
'            ''<td align="center"><b>'' || r.solicitante_contato || ''</b></td>'' ||',
'            ''<td align="center"><a href="#">'' || r.processo_documento || ''</a></td>'' ||',
'            ''<td align="center"><b style="color:blue;">'' || r.autorizacao || ''</b></td>'' ||',
'            ''<td align="center">'' || r.evento || ''</td>'' ||',
'            ''<td align="center"><b style="color:red;">'' || r.data_evento || ''</b></td>'' ||',
'            ''</tr>'';',
'    END LOOP;',
'',
'    l_body := l_body || ''<ul>'' || l_lista || ''</ul><br>'';',
'',
'    l_body := l_body ||',
'        ''<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse; width:100%;">'' ||',
'        ''<tr style="background-color:#d3d3d3; color:red; font-weight:bold;">'' ||',
'        ''<th>COR</th>'' ||',
unistr('        ''<th>DATA DA SOLICITA\00C7\00C3O</th>'' ||'),
'        ''<th>SOLICITADO POR</th>'' ||',
'        ''<th>PROCESSO / DOCUMENTO</th>'' ||',
unistr('        ''<th>AUTORIZA\00C7\00C3O</th>'' ||'),
'        ''<th>EVENTO</th>'' ||',
'        ''<th>DATA DO EVENTO</th>'' ||',
'        ''</tr>'' ||',
'        l_tabela ||',
'        ''</table><br><br>'';',
'    ',
'    l_body := l_body ||',
unistr('        ''Solicito que busquem essas pel\00EDculas na ASQUALOG em <b>'' ||'),
'        TO_CHAR(TO_DATE(:P171_DAT_RETIRADA, ''DD/MM/YYYY''), ''DD/MM/YYYY'') ||',
unistr('        ''</b>, \00E0s '' || :P171_HOR_ENTREGA || ''.<br><br>'';'),
'',
'    l_body := l_body ||',
'        ''Atenciosamente,<br><br>'' ||',
'        :P171_USUARIO || ''<br>'' ||',
unistr('        ''Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'' ||'),
unistr('        ''Senado Federal \2013 Diretoria-Geral<br>'' ||'),
unistr('        ''Via N2 \2013 Gr\00E1fica, Bloco 10, Subsolo, Sala 17<br>'' ||'),
unistr('        ''70165-900 Bras\00EDlia \2013 DF<br>'' ||'),
'        ''(61) 3303-3018'';',
'',
'    APEX_MAIL.SEND(',
'        p_to        => ''marcelo.kobayashi@senado.leg.br'',',
'        p_from      => ''asqualog@senado.leg.br'',',
unistr('        p_subj      => ''Solicita\00E7\00E3o de retirada de pel\00EDculas'','),
'        p_body      => NULL,',
'        p_body_html => l_body',
'    );',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'',
'    UPDATE ilu_iluminacao',
'    SET ind_email = ''S'',',
'        ind_email_atual = ''N''',
'    WHERE ind_email_atual = ''S'';',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>458007760220518521
);
end;
