'  ''file1'' as "filename",',
'  cursor(',
'    select',
'      cursor(',
'        select',
'          processo_documento as "processo",',
'          TO_CHAR(MAX(dat_inicio), ''DD/MM/YYYY'')    as "data_inicio",',
'          TO_CHAR(MAX(dat_termino), ''DD/MM/YYYY'')   as "data_fim",',
'          cor                as "cor",',
'          regexp_replace(evento, ''\s+'', '' '') as "evento",',
'          CASE',
unistr('            WHEN MAX(tip_iluminacao) = ''Ilumina\00E7\00E3o Completa'' THEN :P172_INT_COMPLETA'),
'            WHEN MAX(tip_iluminacao) = ''Anexo I'' THEN :P172_INT_ANEXO',
unistr('            WHEN MAX(tip_iluminacao) = ''C\00FApula'' THEN :P172_INT_CUPULA'),
'          END AS "peliculas_inteiras",',
'          CASE',
unistr('            WHEN MAX(tip_iluminacao) = ''Ilumina\00E7\00E3o Completa'' THEN :P172_CORT_COMPLETA'),
'            WHEN MAX(tip_iluminacao) = ''Anexo I'' THEN :P172_CORT_ANEXO',
unistr('            WHEN MAX(tip_iluminacao) = ''C\00FApula'' THEN :P172_CORT_CUPULA'),
'          END AS "peliculas_cortadas"',
'        from ilu_iluminacao',
'        where ind_email_atual = ''S''',
unistr('            and tip_iluminacao <> ''Proje\00E7\00E3o'''),
'        group by',
'            processo_documento,',
'            cor,',
'            evento,',
'            solicitante_contato',
'      ) as "ilu",',
'      :P172_DAT_ENTREGA as "data_entrega",',
'      :P172_USUARIO     as "usuario",',
'      :P172_HORA        as "hora_entrega"',
