,p_action=>'PLUGIN_BE.APEXRND.AOP_DA'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P173_USUARIO'
,p_attribute_04=>'docx'
,p_attribute_05=>'SQL'
,p_attribute_06=>'APEX'
,p_attribute_07=>'template_os_ceb.docx'
,p_attribute_11=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'  ''file1'' as "filename",',
'  cursor(',
'    select',
'      cursor(',
'        select',
'          i.processo_documento as "processo",',
'',
'          TO_CHAR(MIN(h.dat), ''DD/MM/YYYY'') as "data_inicio",',
'          TRIM(TO_CHAR(',
'            MIN(h.dat),',
'            ''DAY'',',
'            ''NLS_DATE_LANGUAGE=PORTUGUESE''',
'          )) as "dia_semana_inicio",',
'',
'          TO_CHAR(MAX(h.dat), ''DD/MM/YYYY'') as "data_fim",',
'          TRIM(TO_CHAR(',
'            MAX(h.dat),',
'            ''DAY'',',
'            ''NLS_DATE_LANGUAGE=PORTUGUESE''',
'          )) as "dia_semana_fim",',
'',
'          MIN(h.hor_inicio) as "hor_inicio",',
'          MAX(h.hor_fim)    as "hor_fim",',
'',
'          regexp_replace(i.evento, ''\s+'', '' '') as "evento"',
'',
'        from ilu_iluminacao i',
'        join ilu_hor_projecao h',
'          on h.fk_id_iluminacao = i.id_iluminacao',
'',
'        where i.ind_email_atual = ''S''',
'          and h.ind_teste = ''S''',
unistr('          and i.tip_iluminacao = ''Proje\00E7\00E3o'''),
'',
'        group by',
'          i.processo_documento,',
'          i.evento',
'      ) as "ilu_teste",',
'      cursor(',
'        select',
'          i.processo_documento as "processo",',
'',
'         CASE',
'              WHEN MIN(h.dat) = MAX(h.dat) THEN',
'                   TO_CHAR(MIN(h.dat), ''DD/MM/YYYY'') ||',
'                   '' ('' ||',
'                   TRIM(TO_CHAR(',
'                     MIN(h.dat),',
'                     ''DAY'',',
'                     ''NLS_DATE_LANGUAGE=PORTUGUESE''',
'                   )) || '')''',
'              ELSE',
'                   TO_CHAR(MIN(h.dat), ''DD/MM/YYYY'') ||',
'                   '' ('' ||',
'                   TRIM(TO_CHAR(',
'                     MIN(h.dat),',
'                     ''DAY'',',
'                     ''NLS_DATE_LANGUAGE=PORTUGUESE''',
'                   )) || '')'' ||',
'                   '' a '' ||',
'                   TO_CHAR(MAX(h.dat), ''DD/MM/YYYY'') ||',
'                   '' ('' ||',
'                   TRIM(TO_CHAR(',
'                     MAX(h.dat),',
'                     ''DAY'',',
'                     ''NLS_DATE_LANGUAGE=PORTUGUESE''',
'                   )) || '')''',
'            END AS "periodo_extenso",',
'          ',
'          MIN(h.hor_inicio) as "hor_inicio",',
'          MAX(h.hor_fim)    as "hor_fim",',
'',
'          regexp_replace(i.evento, ''\s+'', '' '') as "evento"',
'',
'        from ilu_iluminacao i',
'        join ilu_hor_projecao h',
'          on h.fk_id_iluminacao = i.id_iluminacao',
'',
'        where i.ind_email_atual = ''S''',
'          and h.ind_teste = ''N''',
unistr('          and i.tip_iluminacao = ''Proje\00E7\00E3o'''),
'',
'        group by',
'          i.processo_documento,',
'          i.evento',
'      ) as "ilu_oficial",',
'',
'      :P173_USUARIO as "usuario"',
'',
'    from dual',
'  ) as "data"',
'from dual;'))
,p_wait_for_result=>'Y'
);
