wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(459238076892702813)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Enviar Email'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_body   CLOB;',
'    ',
'    l_id     NUMBER;',
'    v_tem_cd    NUMBER := 0;',
'',
'    v_blob      BLOB;',
'    v_mime      VARCHAR2(200);',
'    v_filename  VARCHAR2(200);',
'',
'    v_falta_sf    NUMBER := 0;',
'    v_falta_cd    NUMBER := 0;',
'BEGIN    ',
'    SELECT',
'        SUM(CASE WHEN qtd_sf = 0 THEN 1 ELSE 0 END) AS falta_sf,',
'        SUM(CASE WHEN qtd_cd = 0 THEN 1 ELSE 0 END) AS falta_cd',
'    INTO',
'        v_falta_sf,',
'        v_falta_cd',
'    FROM',
'        (',
'            SELECT',
'                MAX(i.id_iluminacao) AS id_iluminacao_principal,',
'                SUM(CASE WHEN ap.tip_arquivo = ''SF'' THEN 1 ELSE 0 END) AS qtd_sf,',
'                SUM(CASE WHEN ap.tip_arquivo = ''CD'' THEN 1 ELSE 0 END) AS qtd_cd',
'            FROM ilu_iluminacao i',
'            LEFT JOIN ilu_arq_projecao ap',
'                ON ap.fk_id_iluminacao = i.id_iluminacao',
'            WHERE i.ind_email_atual = ''S''',
unistr('              AND i.tip_iluminacao  = ''Proje\00E7\00E3o'''),
'            GROUP BY',
'                i.cor,',
'                i.evento,',
'                i.processo_documento,',
'                i.solicitante_contato',
'        );',
'    IF v_falta_sf > 0 THEN ',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
unistr('            ''N\00E3o foi poss\00EDvel enviar o e-mail: existe grupo de proje\00E7\00E3o sem autoriza\00E7\00E3o do Senado Federal (SF).'''),
'        );',
'    END IF;',
'',
unistr('    -- Cabe\00E7alho fixo'),
'    v_body :=',
'        ''Boa noite,<br><br>'' ||',
unistr('        ''Solicito, por gentileza, o desligamento programado da ilumina\00E7\00E3o '' ||'),
unistr('        ''para realiza\00E7\00E3o de proje\00E7\00E3o mapeada na fachada do Pal\00E1cio do Congresso Nacional, '' ||'),
unistr('        ''conforme autoriza\00E7\00E3o do Senado Federal anexa e resumo a seguir:<br><br>'';'),
'',
'    FOR r IN (',
'        SELECT',
'            MAX(i.id_iluminacao) id_iluminacao,',
'            i.evento,',
'            i.processo_documento,',
'            LISTAGG(DISTINCT NVL(i.autorizacao,''-''), ''<br>'')',
'                WITHIN GROUP (ORDER BY i.autorizacao) autorizacao',
'        FROM ilu_iluminacao i',
'        WHERE i.ind_email_atual = ''S''',
unistr('            AND i.tip_iluminacao = ''Proje\00E7\00E3o'''),
'        GROUP BY',
'            i.cor,',
'            i.evento,',
'            i.processo_documento,',
'            i.solicitante_contato',
'        ORDER BY MIN(i.dat_inicio)',
'    ) LOOP',
'',
'        -- Uma linha POR DIA',
'        FOR h IN (',
'            SELECT',
'                h.dat,',
'                h.hor_inicio,',
'                h.hor_fim,',
'                h.ind_teste',
'            FROM ilu_hor_projecao h',
'            WHERE h.fk_id_iluminacao = r.id_iluminacao',
'            ORDER BY h.dat',
'        ) LOOP',
'',
'            v_body := v_body ||',
unistr('                ''&nbsp;&nbsp;&nbsp;\2022 '' ||'),
'                TO_CHAR(h.dat, ''DD/MM/YYYY'') || '' ('' ||',
'                TO_CHAR(h.dat, ''Day'', ''NLS_DATE_LANGUAGE=PORTUGUESE'') || ''), das '' ||',
unistr('                h.hor_inicio || '' \00E0s '' || h.hor_fim || '' \2013 '' ||'),
'',
'                CASE',
'                    WHEN h.ind_teste = ''S''',
unistr('                        THEN ''teste t\00E9cnico em alus\00E3o ao '' || r.evento'),
unistr('                    ELSE ''proje\00E7\00E3o em alus\00E3o ao '' || r.evento'),
'                END',
'                || ''<br>'';',
'',
'        END LOOP;',
'',
'    END LOOP;',
'',
'    IF v_falta_cd > 0 THEN',
'        v_body := v_body ||',
'            ''<br>'' ||',
unistr('            ''Quando a autoriza\00E7\00E3o da C\00E2mara dos Deputados for expedida, encaminharemos c\00F3pia para ci\00EAncia.<br>'';'),
'    END IF;',
'',
unistr('    -- Rodap\00E9 fixo'),
'    v_body := v_body ||',
'',
'        ''<br><br>'' ||',
unistr('        ''<b>Religamento:</b> Ao t\00E9rmino de cada proje\00E7\00E3o, pedimos o religamento <span style="color:red;"><b>imediato</b></span> da ilumina\00E7\00E3o.<br><br>'' ||'),
'',
unistr('        ''Favor confirmar o agendamento e o atendimento da solicita\00E7\00E3o.<br><br>'' ||'),
'',
'        ''Atenciosamente,<br><br>'' ||',
'',
'        ''<b>'' || :P174_USUARIO || ''</b><br>'' ||',
unistr('        ''Assessor de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'' ||'),
'        ''Diretoria-Geral<br>'' ||',
'        ''+55 (61) 3303-4060<br><br>'';',
'',
unistr('    -- Envio \00FAnico'),
'    l_id := APEX_MAIL.SEND(',
'        p_to        => ''marcelo.kobayashi@senado.leg.br'',',
'        p_from      => ''asqualog@senado.leg.br'',',
unistr('        p_subj      => ''Desligamento programado de ilumina\00E7\00E3o \2013 Proje\00E7\00F5es mapeadas'','),
'        p_body      => NULL,',
'        p_body_html => v_body',
'    );',
'',
'    /* Anexar um arquivo unico no email',
'    apex_mail.add_attachment(',
'        p_mail_id       => l_id,',
'        p_attachment    => v_blob,',
'        p_filename      => v_filename,',
'        p_mime_type     => v_mime',
'    );',
'    */',
'',
'    FOR a IN (',
'        SELECT ap.arq,',
'            ap.filename,',
'            ap.mimetype',
'        FROM ilu_iluminacao i',
'        JOIN ilu_arq_projecao ap ON ap.fk_id_iluminacao = i.id_iluminacao',
'        WHERE i.ind_email_atual = ''S''',
unistr('            AND i.tip_iluminacao = ''Proje\00E7\00E3o'''),
'    ) LOOP',
'        apex_mail.add_attachment(',
'            p_mail_id       => l_id,',
'            p_attachment    => a.arq,',
'            p_filename      => a.filename,',
'            p_mime_type     => a.mimetype',
'        );',
'    END LOOP;',
'',
