wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(458494687849070324)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Inserir Autoriza\00E7\00F5es')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_blob_sf       BLOB;',
'    v_mime_sf       VARCHAR2(200);',
'    v_filename_sf   VARCHAR2(200);',
'',
'    v_blob_cd       BLOB;',
'    v_mime_cd       VARCHAR2(200);',
'    v_filename_cd   VARCHAR2(200);',
'BEGIN',
'    IF :P175_SENADO IS NOT NULL THEN',
'        BEGIN',
'            SELECT blob_content, mime_type, filename',
'            INTO v_blob_sf, v_mime_sf, v_filename_sf',
'            FROM apex_application_temp_files',
'            WHERE name = :P175_SENADO;',
'',
'            INSERT INTO ilu_arq_projecao (',
'                fk_id_iluminacao,',
'                arq,',
'                filename,',
'                mimetype,',
'                tip_arquivo',
'            ) VALUES (',
'                :P175_ID_ILU,',
'                v_blob_sf,',
'                v_filename_sf,',
'                v_mime_sf,',
'                ''SF''',
'            );',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                NULL;',
'        END;',
'    ELSE',
'        RAISE_APPLICATION_ERROR(',
'            -20002,',
unistr('            ''\00C9 obrigat\00F3ria a inclus\00E3o da autoriza\00E7\00E3o do Senado Federal (SF).'''),
'        );',
'    END IF;',
'',
'    IF :P175_CAMARA IS NOT NULL THEN',
'        BEGIN',
'            SELECT blob_content, mime_type, filename',
'            INTO v_blob_cd, v_mime_cd, v_filename_cd',
'            FROM apex_application_temp_files',
'            WHERE name = :P175_CAMARA;',
'',
'            INSERT INTO ilu_arq_projecao (',
'                fk_id_iluminacao,',
'                arq,',
'                filename,',
'                mimetype,',
'                tip_arquivo',
'            ) VALUES (',
'                :P175_ID_ILU,',
'                v_blob_cd,',
'                v_filename_cd,',
'                v_mime_cd,',
'                ''CD''',
'            );',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                NULL;',
'        END;',
'    END IF;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>458494687849070324
);
end;
