,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function pintar_status(relId) {',
'',
'  $(''#'' + relId + '' table tbody tr'').each(function () {',
'',
'    let $linha = $(this);',
'    let $tdStatus = $linha.find(''td[headers="COL_STATUS"]'');',
'',
'    if (!$tdStatus.length) return;',
'',
'    let status = $tdStatus.text().trim();',
'',
'    if (status === ''OK'') {',
'      $linha.css({ backgroundColor: ''#C6EFCE'', fontWeight: ''bold'' });',
'    } ',
'    else if (status === ''Baixo Estoque'') {',
'      $linha.css({ backgroundColor: ''#FFEB9C'', fontWeight: ''bold'' });',
'    } ',
'    else if (status === ''Baixo Contrato'') {',
'      $linha.css({ backgroundColor: ''#DDEBF7'', fontWeight: ''bold'' });',
'    } ',
unistr('    else if (status === ''Cr\00EDtico'') {'),
'      $linha.css({ backgroundColor: ''#F4CCCC'', fontWeight: ''bold'' });',
'    }',
'',
'  });',
'}',
''))
