wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(388011605138556908)
,p_plug_name=>'CQO'
,p_region_name=>'um'
,p_parent_plug_id=>wwv_flow_imp.id(388011444156556906)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(519407038027522983)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    cor_contrato,',
'    nom_cor,',
'    marca,',
'    MAX(CASE',
'            WHEN atual = ''S'' THEN valor',
'        END) AS valor,',
'',
unistr('    -- Quantidade total dispon\00EDvel no contrato'),
'    SUM(CASE ',
'            WHEN ind_contrato = ''S'' AND atual = ''S'' THEN qtd',
'            ELSE 0',
'        END) AS qtd_contrato,',
'',
'    -- Quantidade total no estoque (inteira = 1 ; cortada = 0.5)',
'    SUM(CASE ',
'            WHEN ind_contrato = ''N'' AND tip_estoque = ''Inteira'' THEN qtd * 1',
'            WHEN ind_contrato = ''N'' AND tip_estoque = ''Cortada'' THEN qtd * 0.5',
'            ELSE 0',
'        END) AS qtd_estoque,',
'    ',
'    SUM(CASE',
'            WHEN ind_contrato = ''N'' AND tip_estoque = ''Inteira'' THEN qtd * 1',
'        END) AS qtd_inteira,',
'    ',
'    SUM(CASE',
'            WHEN ind_contrato = ''N'' AND tip_estoque = ''Cortada'' THEN qtd * 1',
'        END) AS qtd_cortada,',
'',
'    -- STATUS DA COR (texto)',
'    CASE',
'        WHEN ',
'            SUM(CASE WHEN ind_contrato = ''S'' AND atual = ''S'' THEN qtd ELSE 0 END) > 50',
'            AND',
'            SUM(CASE ',
'                    WHEN ind_contrato = ''N'' AND tip_estoque=''Inteira'' THEN qtd*1',
'                    WHEN ind_contrato = ''N'' AND tip_estoque=''Cortada'' THEN qtd*0.5',
'                    ELSE 0',
'                END) > 50',
'        THEN ''OK''',
'        WHEN ',
'            SUM(CASE WHEN ind_contrato = ''S'' AND atual = ''S'' THEN qtd ELSE 0 END) > 50',
'            AND',
'            SUM(CASE ',
'                    WHEN ind_contrato = ''N'' AND tip_estoque=''Inteira'' THEN qtd*1',
'                    WHEN ind_contrato = ''N'' AND tip_estoque=''Cortada'' THEN qtd*0.5',
'                    ELSE 0',
'                END) <= 50',
'        THEN ''Baixo Estoque''',
'        WHEN ',
'            SUM(CASE WHEN ind_contrato = ''S'' AND atual = ''S'' THEN qtd ELSE 0 END) <= 50',
'            AND',
'            SUM(CASE ',
'                    WHEN ind_contrato = ''N'' AND tip_estoque=''Inteira'' THEN qtd*1',
'                    WHEN ind_contrato = ''N'' AND tip_estoque=''Cortada'' THEN qtd*0.5',
'                    ELSE 0',
'                END) > 50',
'        THEN ''Baixo Contrato''',
'',
unistr('        ELSE ''Cr\00EDtico'''),
'    END AS status_cor',
'',
'FROM ilu_cor_contrato',
'WHERE fk_id_contrato = :P201_ID_CONTRATO',
'GROUP BY cor_contrato, nom_cor, marca',
'ORDER BY status_cor;',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P201_ID_CONTRATO'
