wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(388015337924556945)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Adicionar Contrato'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_mime      VARCHAR2(200);',
'    l_filename  VARCHAR2(200);',
'',
'    l_count     NUMBER;',
'BEGIN',
'    SELECT blob_content, mime_type, filename',
'    INTO l_blob, l_mime, l_filename',
'    FROM apex_application_temp_files',
'    WHERE name = :P202_CONTRATO;',
'',
'    IF :P202_DAT_INICIO > :P202_DAT_TERMINO THEN',
unistr('        RAISE_APPLICATION_ERROR(-22021, ''Data de in\00EDcio deve ser anterior ou igual \00E0 data de t\00E9rmino.'');'),
'    END IF;',
'',
'    SELECT COUNT(*) INTO l_count',
'    FROM ilu_contrato',
'    WHERE cod_contrato = :P202_COD_CONTRATO;',
'',
'    IF l_count > 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-22022, ''Esse contrato j\00E1 est\00E1 cadastrado no banco de dados.'');'),
'    END IF;',
'',
'    INSERT INTO ilu_contrato (',
'        cod_contrato,',
'        dat_inicio,',
'        dat_termino,',
'        arq_contrato,',
'        mimetype,',
'        filename,',
'        nom_contratado',
'    ) VALUES (',
'        :P202_COD_CONTRATO,',
'        :P202_DAT_INICIO,',
'        :P202_DAT_TERMINO,',
'        l_blob,',
'        l_mime,',
'        l_filename,',
'        :P202_NOM_CONTRATO',
'    )',
'    RETURNING id_contrato INTO :P202_ID_PARAMETRO;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>388015337924556945
);
end;
