wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(410072762018164806)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Inserir Termo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_mime      VARCHAR2(200);',
'    l_filename  VARCHAR2(200);',
'BEGIN',
'    SELECT blob_content, mime_type, filename',
'    INTO l_blob, l_mime, l_filename',
'    FROM apex_application_temp_files',
'    WHERE name = :P221_ARQUIVO;',
'',
'    INSERT INTO ilu_aditivos (',
'        tip_aditivo,',
'        arq_aditivo,',
'        mimetype,',
'        filename,',
'        fk_id_contrato,',
'        nov_dat_fim,',
'        num_processo,',
'        link_processo',
'    ) VALUES (',
'        :P221_TIP_ADITIVO,',
'        l_blob,',
'        l_mime,',
'        l_filename,',
'        :P221_ID_CONTRATO,',
'        :P221_NOVA_DAT_FIM,',
'        :P221_NUM_PROCESSO,',
'        :P221_LINK',
'    );',
'',
'    UPDATE ilu_contrato',
'    SET dat_termino = :P221_NOVA_DAT_FIM',
'    WHERE id_contrato = :P221_ID_CONTRATO;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>410072762018164806
);
end;
