,p_event_id=>wwv_flow_imp.id(402341458636008643)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'PLUGIN_BE.APEXRND.AOP_DA'
,p_attribute_04=>'docx'
,p_attribute_05=>'SQL'
,p_attribute_06=>'APEX'
,p_attribute_07=>'template.docx'
,p_attribute_11=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'  ''file1'' as "filename",',
'  cursor(',
'    select',
'      iof.processo_pagamento as "processo",',
'      iof.nota_empenho       as "nota_empenho",',
'      TO_CHAR(iof.dat_estimada, ''DD/MM/YYYY'')       as "data_estimada",',
'      cursor(',
'        select',
'          icf.cor_contrato as "cor_contrato",',
'          icf.qtd          as "qtd",',
'          icf.marca || icf.obs as "marca_obs"',
'        from ilu_cor_fornecimento icf',
'        where icf.fk_id_ordem_fornecimento = :P232_ID_ORDEM',
'        order by icf.nom_cor',
'      ) as "items",',
'      cursor(',
'          select',
'            row_number() over (order by icf.id_cor_fornecimento) as "item",',
'            icc.nom_cor                                         as "cor",',
'            (icc.qtd - icf.qtd)                                 as "qtd"',
'          from ilu_cor_fornecimento icf',
'          join ilu_cor_contrato icc',
'            on icc.cor_contrato = icf.cor_contrato',
'           and icc.ind_contrato = ''S''',
'           and icc.atual        = ''S''',
'           and icc.fk_id_contrato = :P232_ID_CONTRATO',
'          where icf.fk_id_ordem_fornecimento = :P232_ID_ORDEM',
'          order by icc.nom_cor',
'      ) as "cores"',
'    from ilu_ordem_fornecimento iof',
'    where iof.id_ordem_fornecimento = :P232_ID_ORDEM',
'  ) as "data"',
'from dual;',
''))
,p_wait_for_result=>'Y'
);
