wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(394584558073621522)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Adicionar OF'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_mime      VARCHAR2(200);',
'    l_filename  VARCHAR2(200);',
'BEGIN',
'    FOR cor IN (',
'        SELECT cor_contrato, qtd',
'        FROM ilu_cor_fornecimento',
'        WHERE fk_id_ordem_fornecimento = :P232_ID_ORDEM',
'    ) LOOP',
'        UPDATE ilu_cor_contrato',
'        SET qtd = qtd - cor.qtd',
'        WHERE fk_id_contrato = :P232_ID_CONTRATO',
'            AND cor_contrato = cor.cor_contrato',
'            AND ind_contrato = ''S'';',
'    END LOOP;',
'',
'    SELECT blob_content, mime_type, filename',
'    INTO l_blob, l_mime, l_filename',
'    FROM apex_application_temp_files',
'    WHERE name = :P232_ARQUIVO;',
'',
'    UPDATE ilu_ordem_fornecimento',
'    SET arq_ordem_fornecimento = l_blob,',
'        mimetype = l_mime,',
'        filename = l_filename',
'    WHERE id_ordem_fornecimento = :P232_ID_ORDEM;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>394584558073621522
);
end;
