wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(426381025838020350)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cancelar OF'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    FOR cor IN (',
'        SELECT cor_contrato, qtd',
'        FROM ilu_cor_fornecimento',
'        WHERE fk_id_ordem_fornecimento = :P233_ID_ORDEM',
'    ) LOOP',
'        UPDATE ilu_cor_contrato',
'        SET qtd = qtd + cor.qtd',
'        WHERE fk_id_contrato = :P233_ID_CONTRATO',
'            AND cor_contrato = cor.cor_contrato',
'            AND ind_contrato = ''S''',
'            AND atual = ''S'';',
'    END LOOP;',
'',
'    DELETE FROM ilu_cor_fornecimento',
'    WHERE fk_id_ordem_fornecimento = :P233_ID_ORDEM;',
'',
'    DELETE FROM ilu_ordem_fornecimento',
'    WHERE id_ordem_fornecimento = :P233_ID_ORDEM;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(426380903626020349)
,p_internal_uid=>426381025838020350
);
