 p_id=>wwv_flow_imp.id(448396428230438301)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Confirmar Altera\00E7\00F5es')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE ilu_ordem_fornecimento',
'    SET documento_solicitacao = :P233_DOCUMENTO_SOLICITACAO,',
'        link_solicitacao = :P233_LINK_SOLICITACAO,',
