,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_mime      VARCHAR2(200);',
'    l_filename  VARCHAR2(200); ',
'BEGIN',
'    SELECT blob_content, mime_type, filename',
'    INTO l_blob, l_mime, l_filename',
'    FROM apex_application_temp_files',
'    WHERE name = :P251_ARQ;',
'',
'    INSERT INTO ilu_aditivos(',
'        tip_aditivo,',
'        arq_aditivo,',
'        mimetype,',
'        filename,',
'        fk_id_contrato,',
'        num_processo,',
'        link_processo',
'    ) VALUES (',
'        :P251_TIP_ADITIVO,',
'        l_blob,',
'        l_mime,',
'        l_filename,',
'        :P251_ID_CONTRATO,',
'        :P251_NUM_PROCESSO,',
