wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(410387886408983107)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirmar cores'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE ilu_cor_contrato',
'    SET atual = NULL',
'    WHERE atual = ''X'';',
'',
'    DELETE FROM ilu_cor_aditivos',
'    WHERE cor_subs IS NOT NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(391133243316536247)
,p_internal_uid=>410387886408983107
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(410388072219983109)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cancelar TA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_tipo  VARCHAR2(100);',
'BEGIN',
'    SELECT tip_aditivo INTO v_tipo',
'    FROM ilu_aditivos',
'    WHERE id_aditivo = :P252_ID_ADITIVO;',
'',
'    IF v_tipo = ''Quantitativo'' THEN',
'        FOR r IN (',
'            SELECT cor_contrato, qtd',
'            FROM ilu_cor_aditivos',
'            WHERE fk_id_aditivo = :P252_ID_ADITIVO',
'                AND tip_aditivo = ''Quantitativo''',
'        )',
'        LOOP',
'            UPDATE ilu_cor_contrato',
'            SET qtd = qtd - r.qtd',
'            WHERE cor_contrato = r.cor_contrato',
'                AND atual = ''S''',
'                AND ind_contrato = ''S''',
'                AND fk_id_contrato = :P252_ID_CONTRATO;',
'        END LOOP;',
'',
'        DELETE FROM ilu_cor_aditivos',
'        WHERE fk_id_aditivo = :P252_ID_ADITIVO',
'            AND tip_aditivo = ''Quantitativo'';',
'    ',
'    ELSIF v_tipo = ''Qualitativo'' THEN',
'        FOR n IN (',
'            SELECT id_cor_aditivo, cor_contrato',
'            FROM ilu_cor_aditivos',
'            WHERE fk_id_aditivo = :P252_ID_ADITIVO',
'                AND tip_aditivo = ''Qualitativo''',
'                AND cor_subs IS NULL',
'        )',
'        LOOP',
'            FOR r IN (',
'                SELECT cor_contrato, qtd',
'                FROM ilu_cor_aditivos',
'                WHERE cor_subs = n.id_cor_aditivo',
'            )',
'            LOOP',
'                UPDATE ilu_cor_contrato',
'                SET qtd = qtd + r.qtd',
'                WHERE cor_contrato = r.cor_contrato',
'                    AND ind_contrato = ''S''',
'                    AND atual = ''S''',
'                    AND fk_id_contrato = :P252_ID_CONTRATO;',
'            END LOOP;',
'',
'            DELETE FROM ilu_cor_contrato',
'            WHERE cor_contrato = n.cor_contrato',
'                AND ind_contrato = ''S''',
'                AND atual = ''S''',
'                AND fk_id_contrato = :P252_ID_CONTRATO;',
'',
'            DELETE FROM ilu_cor_aditivos',
'            WHERE cor_subs = n.id_cor_aditivo',
'                AND fk_id_aditivo = :P252_ID_ADITIVO;',
'        END LOOP;',
'         ',
'        DELETE FROM ilu_cor_aditivos',
'        WHERE fk_id_aditivo = :P252_ID_ADITIVO',
'            AND tip_aditivo = ''Qualitativo''',
'            AND cor_subs IS NULL;',
'    ',
unistr('    ELSIF v_tipo = ''Revis\00E3o'' THEN'),
'        DECLARE',
'            V_cor   VARCHAR2(200);',
'            v_qtd   NUMBER;',
'            v_val   NUMBER;',
'        BEGIN',
'            SELECT cor_contrato, qtd, valor',
'            INTO v_cor, v_qtd, v_val',
'            FROM ilu_cor_aditivos',
'            WHERE fk_id_aditivo = :P252_ID_ADITIVO',
unistr('                AND tip_aditivo = ''Revis\00E3o'';'),
'',
'            DELETE FROM ilu_cor_contrato',
'            WHERE cor_contrato = v_cor',
'                AND valor = v_val',
'                AND fk_id_contrato = :P252_ID_CONTRATO',
'                AND atual = ''S''',
'                AND ind_contrato= ''S'';',
'            ',
'            UPDATE ilu_cor_contrato',
'            SET atual = ''S''',
'            WHERE cor_contrato = v_cor',
'                AND fk_id_contrato = :P252_ID_CONTRATO',
'                AND atual = ''X''',
'                AND ind_contrato = ''S'';',
'',
'            DELETE FROM ilu_cor_aditivos',
'            WHERE fk_id_aditivo = :P252_ID_ADITIVO',
unistr('                AND tip_aditivo = ''Revis\00E3o'';'),
'        END;',
'',
'    ELSIF v_tipo = ''Ambos'' THEN',
'        FOR r IN (',
'            SELECT cor_contrato, qtd',
'            FROM ilu_cor_aditivos',
'            WHERE fk_id_aditivo = :P252_ID_ADITIVO',
'                AND tip_aditivo = ''Quantitativo''',
'        )',
'        LOOP',
'            UPDATE ilu_cor_contrato',
'            SET qtd = qtd - r.qtd',
'            WHERE cor_contrato = r.cor_contrato',
'                AND ind_contrato = ''S''',
'                AND atual = ''S''',
'                AND fk_id_contrato = :P252_ID_CONTRATO;',
'        END LOOP;',
'',
'        DELETE FROM ilu_cor_aditivos',
'        WHERE fk_id_aditivo = :P252_ID_ADITIVO',
'            AND tip_aditivo = ''Quantitativo'';',
'',
'        FOR n IN (',
'            SELECT id_cor_aditivo, cor_contrato',
'            FROM ilu_cor_aditivos',
'            WHERE fk_id_aditivo = :P252_ID_ADITIVO',
'                AND tip_aditivo = ''Qualitativo''',
'                AND cor_subs IS NULL',
'        )',
'        LOOP',
'            FOR r IN (',
'                SELECT cor_contrato, qtd',
'                FROM ilu_cor_aditivos',
'                WHERE cor_subs = n.id_cor_aditivo',
'            )',
'            LOOP',
'                UPDATE ilu_cor_contrato',
'                SET qtd = qtd + r.qtd',
'                WHERE cor_contrato = r.cor_contrato',
'                    AND ind_contrato = ''S''',
'                    AND atual = ''S''',
'                    AND fk_id_contrato = :P252_ID_CONTRATO;',
'            END LOOP;',
'',
'            DELETE FROM ilu_cor_contrato',
'            WHERE cor_contrato = n.cor_contrato',
'                AND ind_contrato = ''S''',
'                AND atual = ''S''',
'                AND fk_id_contrato = :P252_ID_CONTRATO;',
'',
'            DELETE FROM ilu_cor_aditivos',
'            WHERE cor_subs = n.id_cor_aditivo',
'                AND fk_id_aditivo = :P252_ID_ADITIVO;',
'        END LOOP;',
'',
'        DELETE FROM ilu_cor_aditivos',
'        WHERE fk_id_aditivo = :P252_ID_ADITIVO',
'            AND tip_aditivo = ''Qualitativo''',
'            AND cor_subs IS NULL;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(391133357128536248)
,p_internal_uid=>410388072219983109
);
end;
