unistr('        RAISE_APPLICATION_ERROR(-22701, ''Essa cor j\00E1 est\00E1 cadastrada nesse contrato.'');'),
'    END IF;',
'',
'    INSERT INTO ilu_cor_contrato (',
'        cor_contrato,',
'        nom_cor,',
'        marca,',
'        ind_contrato,',
'        qtd,',
'        valor,',
'        obs,',
'        fk_id_contrato,',
'        atual',
'    ) VALUES (',
'        :P270_COR_CONTRATO,',
'        :P270_NOM_COR,',
'        :P270_MARCA,',
'        ''S'',',
'        :P270_QTD,',
'        :P270_VALOR,',
'        :P270_OBS,',
'        :P270_FK_ID_CONTRATO,',
'        ''S''',
'    );',
'END;'))
,p_process_clob_language=>'PLSQL'
