wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(391132161760536236)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Substituir Cores'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_cores     apex_t_varchar2;',
'    v_qtds      apeX_t_varchar2;',
'    v_cor       VARCHAR2(4000);',
'    v_qtd       NUMBER;',
'',
'    v_valor_unit    NUMBER;',
'    v_total_sub     NUMBER := 0;',
'    v_total_novo    NUMBER := 0;',
'',
'    v_qtd_atual     NUMBER;',
'',
'    v_id_nova_cor   NUMBER;',
'    v_min_count     NUMBER;',
'BEGIN',
'    v_cores := apex_string.split(:P274_CORES_SUBSTITUTAS, '':'');',
'    v_qtds := apex_string.split(:P274_LIXO, '':'');',
'',
'    IF v_cores.COUNT != v_qtds.COUNT THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''Erro: O n\00FAmero de Cores ('' || v_cores.COUNT || '') n\00E3o corresponde ao n\00FAmero de Quantidades ('' || v_qtds.COUNT || ''). Verifique os dados de entrada.'');'),
'    END IF;',
'',
'    v_min_count := v_cores.COUNT;',
'',
'    FOR i in 1 .. v_min_count LOOP',
'        v_cor := v_cores(i);',
'        v_qtd := v_qtds(i);',
'',
'        SELECT valor INTO v_valor_unit',
'        FROM ilu_cor_contrato',
'        WHERE cor_contrato = v_cor',
'            AND ind_contrato = ''S''',
'            AND atual = ''S''',
'            AND fk_id_contrato = :P274_ID_CONTRATO;',
'',
'        v_total_sub := v_total_sub + (v_valor_unit * v_qtd);',
'    END LOOP;',
'',
'    v_total_novo := :P274_QTD * :P274_VALOR;',
'',
'    IF v_total_sub != v_total_novo THEN',
unistr('        RAISE_APPLICATION_ERROR(-20002, ''O valor total das cores substitu\00EDdas('' || v_total_sub || '') n\00E3o bate com o valor da nova cor ('' || v_total_novo || '').'');'),
'    END IF;',
'    ',
'    FOR i IN 1 .. v_min_count LOOP',
'        v_cor := v_cores(i);',
'        v_qtd := v_qtds(i);',
'',
'        SELECT qtd INTO v_qtd_atual',
'        FROM ilu_cor_contrato',
'        WHERE cor_contrato = v_cor',
'            AND ind_contrato = ''S''',
'            AND atual = ''S''',
'            AND fk_id_contrato = :P274_ID_CONTRATO;',
'',
'        IF v_qtd_atual < v_qtd THEN',
unistr('            RAISE_APPLICATION_ERROR(-20003, ''N\00E3o \00E9 poss\00EDvel subtrair '' || v_qtd || '' da cor '' || v_cor || ''. Quantidade atual \00E9 '' || v_qtd_atual || ''.'');'),
'        END IF; ',
'    END LOOP;',
'',
'    INSERT INTO ilu_cor_aditivos (',
'        nom_cor,',
'        qtd,',
'        fk_id_aditivo,',
'        cor_contrato,',
'        marca,',
'        valor,',
'        tip_aditivo',
'    ) VALUES (',
'        :P274_NOM_COR,',
'        :P274_QTD,',
'        :P274_ID_ADITIVO,',
'        :P274_COR_CONTRATO,',
'        :P274_MARCA,',
'        :P274_VALOR,',
'        ''Qualitativo''',
'    )',
'    RETURNING id_cor_aditivo INTO v_id_nova_cor;',
'',
'    INSERT INTO ilu_cor_contrato (',
'        cor_contrato,',
'        nom_cor,',
'        marca,',
'        ind_contrato,',
'        qtd,',
'        fk_id_contrato,',
'        valor,',
'        atual',
'    ) VALUES (',
'        :P274_COR_CONTRATO,',
'        :P274_NOM_COR,',
'        :P274_MARCA,',
'        ''S'',',
'        :P274_QTD,',
'        :P274_ID_CONTRATO,',
'        :P274_VALOR,',
'        ''S''',
'    );',
'    ',
'    FOR i IN 1 .. v_cores.COUNT LOOP',
'        v_cor := v_cores(i);',
'        v_qtd := v_qtds(i);',
'',
'        UPDATE ilu_cor_contrato',
'        SET qtd = qtd - v_qtd',
'        WHERE cor_contrato = v_cor',
'            AND ind_contrato = ''S''',
'            AND atual = ''S''',
'            AND fk_id_contrato = :P274_ID_CONTRATO;',
'',
'        INSERT INTO ilu_cor_aditivos (',
'            nom_cor,',
'            qtd,',
'            fk_id_aditivo,',
'            cor_contrato,',
'            marca,',
'            valor,',
'            tip_aditivo,',
'            cor_subs',
'        )',
'        SELECT nom_cor,',
'            v_qtd,',
'            :P274_ID_ADITIVO,',
'            cor_contrato,',
'            marca,',
'            valor,',
'            ''Qualitativo'',',
'            v_id_nova_cor',
'        FROM ilu_cor_contrato',
'        WHERE cor_contrato = v_cor',
'            AND atual = ''S''',
'            AND ind_contrato = ''S''',
'            AND fk_id_contrato = :P274_ID_CONTRATO;',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>391132161760536236
);
end;
