 p_id=>wwv_flow_imp.id(410387566306983104)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Apagar Cor'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_id_contrato   NUMBER;',
'',
'    l_cor_nova      VARCHAR2(200);',
'BEGIN',
'    SELECT cor_contrato INTO l_cor_nova',
'    FROM ilu_cor_aditivos',
'    WHERE id_cor_aditivo = :P275_ID_COR_ADITIVO;',
'',
'    SELECT ia.fk_id_contrato INTO l_id_contrato',
'    FROM ilu_aditivos ia',
'    JOIN ilu_cor_aditivos ica ON ica.fk_id_aditivo = ia.id_aditivo',
'    WHERE ica.id_cor_aditivo = :P275_ID_COR_ADITIVO;',
'',
'    FOR r IN (',
'        SELECT id_cor_aditivo,',
'            qtd,',
'            cor_contrato',
'        FROM ilu_cor_aditivos',
'        WHERE cor_subs = :P275_ID_COR_ADITIVO',
'    )',
'    LOOP',
'        UPDATE ilu_cor_contrato',
'        SET qtd = qtd + r.qtd',
'        WHERE cor_contrato = r.cor_contrato',
'            AND ind_contrato = ''S''',
'            AND atual = ''S''',
'            AND fk_id_contrato = l_id_contrato;',
'        ',
'        DELETE FROM ilu_cor_aditivos',
'        WHERE id_cor_aditivo = r.id_cor_aditivo;',
'       ',
'    END LOOP;',
'',
'    DELETE FROM ilu_cor_contrato',
'    WHERE cor_contrato = l_cor_nova',
'        AND fk_id_contrato = l_id_contrato',
'        AND ind_contrato = ''S''',
'        AND ATUAL = ''S'';',
'',
'    DELETE FROM ilu_cor_aditivos',
'    WHERE id_cor_aditivo = :P275_ID_COR_ADITIVO;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>410387566306983104
);
end;
