 p_id=>wwv_flow_imp.id(394582435568621501)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Adicionar Cor OF'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_qtd           NUMBER;',
'    l_qtd_of_atual  NUMBER;',
'BEGIN',
'    SELECT qtd INTO l_qtd',
'    FROM ilu_cor_contrato',
'    WHERE ind_contrato = ''S''',
'        AND cor_contrato = :P276_COR_CONTRATO',
'        AND fk_id_contrato = :P276_ID_CONTRATO;',
'',
'    SELECT NVL(SUM(qtd), 0) INTO l_qtd_of_atual',
'    FROM ilu_cor_fornecimento',
'    WHERE cor_contrato = :P276_COR_CONTRATO',
'        AND fk_id_ordem_fornecimento = :P276_ID_ORDEM;',
'',
'    l_qtd_of_atual := l_qtd_of_atual + :P276_QTD;',
'',
'    IF l_qtd_of_atual > l_qtd THEN',
unistr('        RAISE_APPLICATION_ERROR(-20004, ''Essa quantidade de pel\00EDculas n\00E3o est\00E1 dispon\00EDvel no contrato.'');'),
'    END IF;',
'',
'    INSERT INTO ilu_cor_fornecimento (',
'        cor_contrato,',
'        nom_cor,',
'        marca,',
'        valor,',
'        qtd,',
'        obs,',
'        fk_id_ordem_fornecimento',
'    ) VALUES (',
'        :P276_COR_CONTRATO,',
'        :P276_NOM_COR,',
'        :P276_MARCA,',
'        :P276_VALOR,',
'        :P276_QTD,',
'        :P276_OBS,',
'        :P276_ID_ORDEM',
'    )',
'    RETURNING id_cor_fornecimento INTO :P276_ID_COR;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>394582435568621501
);
end;
