'DECLARE',
'    l_cor   VARCHAR2(200);',
'    l_marca VARCHAR2(200);',
'    l_valor VARCHAR2(200);',
'    l_qtd   NUMBER;',
'BEGIN',
'    SELECT MAX(nom_cor), MAX(marca), MAX(valor), MAX(qtd)',
'    INTO l_cor, l_marca, l_valor, l_qtd',
'    FROM ilu_cor_contrato',
'    WHERE cor_contrato = :P278_COR_CONTRATO',
'        AND ind_contrato = ''S''',
'        AND atual = ''S'';',
'',
'    :P278_NOM_COR := l_cor;',
'    :P278_MARCA := l_marca;',
'    :P278_VALOR := l_valor;',
'    :P278_QTD := l_qtd;',
'END;'))
