'    INSERT INTO ilu_cor_aditivos (',
'        nom_cor,',
'        qtd,',
'        fk_id_aditivo,',
'        cor_contrato,',
'        marca,',
'        valor,',
'        tip_aditivo',
'    ) VALUES (',
'        :P278_NOM_COR,',
'        :P278_QTD,',
'        :P278_ID_ADITIVO,',
'        :P278_COR_CONTRATO,',
'        :P278_MARCA,',
'        :P278_NOVO_VALOR,',
unistr('        ''Revis\00E3o'''),
'    );',
'',
'    UPDATE ilu_cor_contrato',
'    SET atual = NULL',
'    WHERE cor_contrato = :P278_COR_CONTRATO',
'        AND ind_contrato = ''S''',
'        AND atual = ''X''',
'        AND fk_id_contrato = :P278_ID_CONTRATO;',
'        ',
'    UPDATE ilu_cor_contrato',
'    SET qtd = 0,',
'        atual = ''X''',
'    WHERE cor_contrato = :P278_COR_CONTRATO',
'        AND ind_contrato = ''S''',
'        AND atual = ''S''',
'        AND fk_id_contrato = :P278_ID_CONTRATO;',
'',
'    INSERT INTO ilu_cor_contrato (',
