wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(410182229743404445)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Apagar Cor'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_id_contrato   NUMBER;',
'BEGIN',
'    SELECT a.fk_id_contrato INTO l_id_contrato',
'    FROM ilu_aditivos a',
'    JOIN ilu_cor_aditivos ca ON a.id_aditivo = ca.fk_id_aditivo',
'    WHERE ca.id_cor_aditivo = :P279_ID_COR_ADITIVO;',
'',
'    DELETE FROM ilu_cor_contrato',
'    WHERE cor_contrato = :P279_COR_CONTRATO',
'        AND ind_contrato = ''S''',
'        AND atual = ''S''',
'        AND fk_id_contrato = l_id_contrato;',
'',
'    UPDATE ilu_cor_contrato',
'    SET qtd = :P279_QTD,',
'        atual = ''S''',
'    WHERE cor_contrato = :P279_COR_CONTRATO',
'        AND ind_contrato = ''S''',
'        AND atual = ''X''',
'        AND fk_id_contrato = l_id_contrato;',
'',
'    DELETE FROM ilu_cor_aditivos',
'    WHERE id_cor_aditivo = :P279_ID_COR_ADITIVO;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>410182229743404445
);
end;
